// Made by Tools/DocsData from the engine: don't edit by hand.
window.VertexSamples = {"CodeOnly/Program.cs":"using System.Numerics;\n\nusing Vertex;\nusing Vertex.Input;\nusing Vertex.Physics;\nusing Vertex.Rendering;\nusing Vertex.UI;\n\n// A whole game in one file, made only in code: roll the ball with WASD and pick up every coin before time runs out.\nnew CoinGame().Run(\"Coin Grab\");\n\n/// <summary>Builds the world when it starts, and keeps score and time.</summary>\npublic class CoinGame : Game\n{\n    public const int CoinCount = 10;\n    public const float TimeLimit = 60f;\n\n    public static int Score { get; set; }\n    public float TimeLeft { get; private set; } = TimeLimit;\n\n    public override void Load()\n    {\n        Score = 0;\n\n        // Light and ground.\n        var sun = new GameObject(\"Sun\");\n        sun.AddComponent<Light>();\n        sun.Transform.EulerAngles = new Vector3(-50f, 30f, 0f);\n        GameObject.CreatePlane(Vector3.Zero, size: 30f, color: new Color(0.35f, 0.55f, 0.35f), name: \"Ground\");\n\n        // Low walls round the edge, so the ball stays in.\n        for (int side = 0; side < 4; side++)\n        {\n            float angle = side * MathF.PI / 2f;\n            var along = new Vector3(MathF.Cos(angle), 0f, MathF.Sin(angle));\n            GameObject wall = GameObject.CreateCube(along * 15f + new Vector3(0f, 0.5f, 0f), new Color(0.5f, 0.45f, 0.4f), \"Wall\");\n            wall.Transform.Scale = side % 2 == 0 ? new Vector3(0.5f, 1f, 30f) : new Vector3(30f, 1f, 0.5f);\n        }\n\n        // The player: a ball that physics rolls about.\n        GameObject ball = GameObject.CreateSphere(new Vector3(0f, 1f, 0f), new Color(0.25f, 0.5f, 1f), \"Ball\");\n        ball.AddComponent<Rigidbody>(body => body.Mass = 1f);\n        ball.AddComponent<Roller>();\n\n        // A camera that follows it.\n        var camera = new GameObject(\"Camera\");\n        camera.AddComponent<Camera>();\n        camera.AddComponent<Follow>(follow => follow.Target = ball);\n\n        for (int i = 0; i < CoinCount; i++) Coin.Make(RandomSpot());\n    }\n\n    public override void Update()\n    {\n        if (Score < CoinCount) TimeLeft = MathF.Max(TimeLeft - Time.DeltaTime, 0f);\n\n        string text = Score == CoinCount ? $\"All {CoinCount} coins with {TimeLeft:0} seconds to spare!\"\n            : TimeLeft <= 0f ? $\"Out of time: {Score} of {CoinCount} coins. Press R to play again.\"\n            : $\"Coins {Score}/{CoinCount}   Time {TimeLeft:0}\";\n        Canvas.DrawText(Font.Default, text, new Vector2(24f, 20f), Color.White, 30f);\n\n        if (InputSystem.GetKeyDown(Key.R))\n        {\n            // Again from the start: a fresh scene, built again.\n            Scene old = Scene.Active;\n            Scene.Active = new Scene();\n            old.Unload();\n            TimeLeft = TimeLimit;\n            Load();\n        }\n    }\n\n    /// <summary>Somewhere on the ground, but not where the ball starts: a coin there would be picked up for free.</summary>\n    public static Vector3 RandomSpot()\n    {\n        while (true)\n        {\n            var spot = new Vector3(Random.Shared.NextSingle() * 24f - 12f, 0.6f, Random.Shared.NextSingle() * 24f - 12f);\n            if (new Vector2(spot.X, spot.Z).Length() > 2.5f) return spot;\n        }\n    }\n}\n\n/// <summary>Pushes the ball the way WASD points, as seen from the camera.</summary>\npublic class Roller : Component\n{\n    public float Push { get; set; } = 12f;\n\n    protected override void FixedUpdate()\n    {\n        float forward = (InputSystem.GetKey(Key.W) ? 1f : 0f) - (InputSystem.GetKey(Key.S) ? 1f : 0f);\n        float right = (InputSystem.GetKey(Key.D) ? 1f : 0f) - (InputSystem.GetKey(Key.A) ? 1f : 0f);\n        GetComponent<Rigidbody>()?.AddForce(new Vector3(right, 0f, -forward) * Push);\n    }\n}\n\n/// <summary>Keeps the camera behind and above its target, looking at it.</summary>\npublic class Follow : Component\n{\n    public GameObject? Target { get; set; }\n    public Vector3 Offset { get; set; } = new(0f, 8f, 10f);\n\n    protected override void Update()\n    {\n        if (Target == null) return;\n        Transform.Position = Vector3.Lerp(Transform.Position, Target.Transform.Position + Offset, MathF.Min(Time.DeltaTime * 5f, 1f));\n        Transform.LookAt(Target.Transform.Position);\n    }\n}\n\n/// <summary>A spinning coin. Touching it scores, and it's gone.</summary>\npublic class Coin : Component\n{\n    public static GameObject Make(Vector3 position)\n    {\n        GameObject coin = GameObject.CreateSphere(position, new Color(1f, 0.8f, 0.2f), \"Coin\");\n        coin.Transform.Scale = new Vector3(0.6f, 0.6f, 0.15f);\n        coin.GetComponent<SphereCollider>()!.IsTrigger = true;\n        coin.AddComponent<Coin>();\n        return coin;\n    }\n\n    protected override void Update() => Transform.EulerAngles += new Vector3(0f, 120f * Time.DeltaTime, 0f);\n\n    protected override void OnTriggerEnter(Collider other)\n    {\n        if (other.GameObject.Name != \"Ball\") return;\n        CoinGame.Score++;\n        GameObject.Destroy();\n    }\n}\n","Duel/Assets/Scripts/DuelHud.cs":"using Vertex;\nusing Vertex.Input;\nusing Vertex.Networking;\nusing Vertex.UI;\n\nnamespace Duel\n{\n    /// <summary>\n    /// The writing on the screen: how connecting is going (Enter finds a match), your health, and the score. Put it on\n    /// the HUD, and point its slots at the HUD's texts.\n    /// </summary>\n    public class DuelHud : Component\n    {\n        public UIText? StatusText { get; set; }\n        public UIText? HealthText { get; set; }\n        public UIText? ScoreText { get; set; }\n\n        private int _mine;\n        private int _theirs;\n\n        protected override void Update()\n        {\n            NetworkManager? network = NetworkManager.Instance;\n            if (InputSystem.GetKeyDown(Key.Enter) && !Network.InSession) network?.QuickMatch();\n\n            if (StatusText != null)\n            {\n                string status = network?.Status ?? \"Offline\";\n                StatusText.Text = status == \"Offline\" ? \"Press Enter to find a match\" : status;\n            }\n\n            if (HealthText != null && network?.LocalPlayer?.GetComponent<Health>() is { } health) HealthText.Text = $\"Health {health.Current:0}\";\n            if (ScoreText != null) ScoreText.Text = $\"{_mine} - {_theirs}\";\n        }\n\n        protected override void OnNetworkEvent(NetworkEvent networkEvent)\n        {\n            if (networkEvent.Name != \"Scored\") return;\n\n            // Who scored is their player: this machine's own, or the other one.\n            if (networkEvent.Values.ElementAtOrDefault(0) is GameObject scorer && scorer == NetworkManager.Instance?.LocalPlayer) _mine++;\n            else _theirs++;\n        }\n    }\n}\n","Duel/Assets/Scripts/Health.cs":"using Vertex;\nusing Vertex.Networking;\n\nnamespace Duel\n{\n    /// <summary>\n    /// A player's health. Hits arrive as \"Hit\" network events on the machine that owns the player; at none left, it tells\n    /// everyone who scored and starts again at the spawn point furthest from the other player.\n    /// </summary>\n    public class Health : Component\n    {\n        public float MaxHealth { get; set; } = 100f;\n\n        /// <summary>How much is left.</summary>\n        public float Current { get; private set; }\n\n        protected override void Start()\n        {\n            Current = MaxHealth;\n        }\n\n        protected override void OnNetworkEvent(NetworkEvent networkEvent)\n        {\n            if (networkEvent.Name != \"Hit\" || !IsMine) return;\n\n            float damage = networkEvent.Values.ElementAtOrDefault(0) as float? ?? 0f;\n            Current -= damage;\n            if (Current > 0f) return;\n\n            // To every script: the scoreboards count it. The second value of a hit is who shot.\n            NetworkScene.SendEvent(\"Scored\", null, NetworkTarget.Everyone, networkEvent.Values.ElementAtOrDefault(1));\n            Respawn();\n        }\n\n        private void Respawn()\n        {\n            Current = MaxHealth;\n            if (SpawnPoint.FurthestFromOthers(GameObject) is { } point)\n            {\n                Transform.Position = point.Transform.WorldPosition;\n                Transform.Rotation = point.Transform.WorldRotation;\n            }\n        }\n    }\n}\n","Duel/Assets/Scripts/PlayerGun.cs":"using Vertex;\nusing Vertex.Audio;\nusing Vertex.Input;\nusing Vertex.Networking;\nusing Vertex.Physics;\nusing Vertex.Rendering;\n\nnamespace Duel\n{\n    /// <summary>\n    /// Shoots where the player looks while the left mouse button is held. A hit tells the player who was hit, on their\n    /// own machine, which is in charge of their health. Everyone sees and hears every shot.\n    /// </summary>\n    public class PlayerGun : Component\n    {\n        public float Damage { get; set; } = 25f;\n\n        [Tooltip(\"Shots a second while the button's held\")]\n        public float FireRate { get; set; } = 5f;\n\n        public float Range { get; set; } = 100f;\n\n        /// <summary>Where shots come from, and the way they go: the camera's object.</summary>\n        public GameObject? Head { get; set; }\n\n        public AudioClip? ShotSound { get; set; }\n\n        /// <summary>A particle system that flashes at the gun on each shot.</summary>\n        public ParticleSystem? MuzzleFlash { get; set; }\n\n        private float _nextShot;\n\n        protected override void Update()\n        {\n            if (!IsMine || !InputSystem.CursorLocked) return;\n            if (!InputSystem.GetMouseButton(MouseButton.Left) || Time.TotalTime < _nextShot) return;\n\n            _nextShot = Time.TotalTime + 1f / FireRate;\n            Shoot();\n        }\n\n        private void Shoot()\n        {\n            NetworkScene.SendEvent(\"Shot\", GameObject, NetworkTarget.Everyone);\n\n            Transform aim = (Head ?? GameObject).Transform;\n            bool hit = GameObject.Scene.Physics.Raycast(aim.WorldPosition, aim.Forward, Range, out RaycastHit found, GetComponent<Collider>());\n            if (hit && found.Collider.GameObject.GetComponent<Health>() != null)\n            {\n                // Told to whoever plays the one hit, with how much it hurt and who shot.\n                NetworkScene.SendEvent(\"Hit\", found.Collider.GameObject, NetworkTarget.Owner, Damage, GameObject);\n            }\n        }\n\n        protected override void OnNetworkEvent(NetworkEvent networkEvent)\n        {\n            if (networkEvent.Name != \"Shot\") return;\n\n            if (ShotSound != null) Sound.PlayAt(ShotSound, Transform.WorldPosition, 0.6f);\n            MuzzleFlash?.Play();\n        }\n    }\n}\n","Duel/Assets/Scripts/PlayerMovement.cs":"using System.Numerics;\n\nusing Vertex;\nusing Vertex.Input;\nusing Vertex.Physics;\n\nnamespace Duel\n{\n    /// <summary>\n    /// Walks the player with WASD, jumps with Space and looks around with the mouse. Every machine has every player, but\n    /// only the one who owns this player moves it: everyone else sees it move through its Network Transform.\n    /// </summary>\n    public class PlayerMovement : Component\n    {\n        [Header(\"Moving\")]\n        public float Speed { get; set; } = 6f;\n        public float JumpSpeed { get; set; } = 5f;\n        public float Gravity { get; set; } = 20f;\n\n        [Header(\"Looking\")]\n        public float MouseSensitivity { get; set; } = 0.15f;\n\n        /// <summary>The camera's object, under the player: it tips up and down while the whole player turns left and right.</summary>\n        public GameObject? Head { get; set; }\n\n        private CharacterController? _character;\n        private float _pitch;\n\n        protected override void Start()\n        {\n            _character = GetComponent<CharacterController>();\n        }\n\n        protected override void Update()\n        {\n            if (!IsMine || _character == null) return;\n\n            // Click in the game to take the mouse, Escape to let it go.\n            if (InputSystem.GetMouseButtonDown(MouseButton.Left)) InputSystem.CursorLocked = true;\n            if (InputSystem.GetKeyDown(Key.Escape)) InputSystem.CursorLocked = false;\n\n            if (InputSystem.CursorLocked) Look();\n            Walk(_character);\n        }\n\n        private void Look()\n        {\n            Vector2 mouse = InputSystem.MouseDelta * MouseSensitivity;\n\n            // Turning left and right turns the whole player; looking up and down only tips the head.\n            Transform.EulerAngles += new Vector3(0f, -mouse.X, 0f);\n            _pitch = Math.Clamp(_pitch - mouse.Y, -85f, 85f);\n            if (Head != null) Head.Transform.EulerAngles = new Vector3(_pitch, 0f, 0f);\n        }\n\n        private void Walk(CharacterController character)\n        {\n            float forward = (InputSystem.GetKey(Key.W) ? 1f : 0f) - (InputSystem.GetKey(Key.S) ? 1f : 0f);\n            float right = (InputSystem.GetKey(Key.D) ? 1f : 0f) - (InputSystem.GetKey(Key.A) ? 1f : 0f);\n            Vector3 move = Transform.Forward * forward + Transform.Right * right;\n            move.Y = 0f;\n            if (move.LengthSquared() > 1f) move = Vector3.Normalize(move);\n            move *= Speed;\n\n            // On the ground it jumps or stays down; in the air it falls faster and faster.\n            float rise = character.Velocity.Y;\n            if (character.IsGrounded) rise = InputSystem.GetKey(Key.Space) ? JumpSpeed : -1f;\n            else rise -= Gravity * Time.DeltaTime;\n\n            character.Velocity = new Vector3(move.X, rise, move.Z);\n            character.Move(Time.DeltaTime);\n        }\n    }\n}\n","Duel/Program.cs":"using Vertex;\n\n// Runs the duel outside the editor, in the scene made with C# scripts; \"--visual\" plays the one made with visual\n// scripts. In the editor, Play plays whichever scene is open.\nstring scene = args.Contains(\"--visual\") ? \"Scenes/Duel (Visual Scripting).scene\" : \"Scenes/Duel (CSharp).scene\";\nnew Game { StartScene = scene }.Run(\"Duel\");\n","NeonCity/Assets/Scripts/CityHud.cs":"using System.Numerics;\n\nusing Vertex;\nusing Vertex.Input;\nusing Vertex.UI;\n\nnamespace NeonCity\n{\n    /// <summary>\n    /// The keys, in a line along the bottom, fading out after a while (H brings them back); and F turns the volumetric fog\n    /// on and off, to see what it adds.\n    /// </summary>\n    public class CityHud : Component\n    {\n        private float _shownFor;\n\n        protected override void Update()\n        {\n            if (InputSystem.GetKeyDown(Key.F)) Scene.Active.Lighting.VolumetricFog = !Scene.Active.Lighting.VolumetricFog;\n            if (InputSystem.GetKeyDown(Key.H)) _shownFor = 0f;\n            _shownFor += Time.DeltaTime;\n\n            float alpha = 1f - Math.Clamp((_shownFor - 12f) / 2f, 0f, 1f);\n            if (alpha <= 0f) return;\n\n            string fog = Scene.Active.Lighting.VolumetricFog ? \"on\" : \"off\";\n            string text = $\"Click to look round    WASD walk    Shift hurry    Space jump    F fog ({fog})    Esc free the mouse\";\n            float size = 18f;\n            Vector2 at = new(24f, Canvas.Height - 44f);\n            Canvas.DrawText(Font.Default, text, at + new Vector2(1.5f, 1.5f), new Color(0f, 0f, 0f, 0.6f * alpha), size);\n            Canvas.DrawText(Font.Default, text, at, new Color(0.9f, 0.92f, 1f, 0.85f * alpha), size);\n        }\n    }\n}\n","NeonCity/Assets/Scripts/ColorCycle.cs":"using Vertex;\nusing Vertex.Rendering;\n\nnamespace NeonCity\n{\n    /// <summary>\n    /// Fades the object's light, and the colour and glow of its mesh's material, round three colours in turn: a big\n    /// advert that keeps changing, and the street it lights.\n    /// </summary>\n    public class ColorCycle : Component\n    {\n        public Color First { get; set; } = new(1f, 0.15f, 0.6f);\n        public Color Second { get; set; } = new(0.1f, 0.75f, 1f);\n        public Color Third { get; set; } = new(0.6f, 0.2f, 1f);\n\n        /// <summary>How long each colour lasts, fading to the next for the last third of it.</summary>\n        public float Seconds { get; set; } = 4f;\n\n        /// <summary>Whether it colours the material's own colour too, not only its glow: for pictures, which it tints.</summary>\n        public bool TintColor { get; set; }\n\n        private Light? _light;\n        private Material? _material;\n\n        protected override void Start()\n        {\n            _light = GetComponent<Light>();\n            _material = GetComponent<MeshRenderer>()?.Material;\n        }\n\n        protected override void Update()\n        {\n            Color[] colors = [First, Second, Third];\n            float t = Time.TotalTime / MathF.Max(Seconds, 0.1f);\n            int index = (int)MathF.Floor(t) % colors.Length;\n            float fade = Math.Clamp((t - MathF.Floor(t) - 0.66f) / 0.34f, 0f, 1f);\n            Color color = Color.Lerp(colors[index], colors[(index + 1) % colors.Length], fade * fade * (3f - 2f * fade));\n\n            if (_light != null) _light.Color = color;\n            if (_material == null) return;\n\n            _material.Emission = color;\n            if (TintColor) _material.Color = Color.Lerp(Color.White, color, 0.5f);\n        }\n    }\n}\n","NeonCity/Assets/Scripts/Flicker.cs":"using Vertex;\nusing Vertex.Rendering;\n\nnamespace NeonCity\n{\n    /// <summary>How a <see cref=\"Flicker\"/> flickers.</summary>\n    public enum FlickerStyle\n    {\n        /// <summary>On, but now and then it stutters, like a neon tube on its way out.</summary>\n        Buzz,\n\n        /// <summary>On and off in a steady beat, like a warning light on a roof.</summary>\n        Blink\n    }\n\n    /// <summary>\n    /// Flickers the object's light and its glow (the emission of its mesh's material) together, as a failing neon sign\n    /// or a blinking warning light does.\n    /// </summary>\n    public class Flicker : Component\n    {\n        public FlickerStyle Style { get; set; } = FlickerStyle.Buzz;\n\n        /// <summary>Buzz: how often it stutters, about every this many seconds. Blink: seconds from one blink to the next.</summary>\n        public float Seconds { get; set; } = 3f;\n\n        /// <summary>How dark it goes when it's off, from 0 (out) to 1 (no darker).</summary>\n        [Range(0f, 1f)]\n        public float Low { get; set; } = 0.08f;\n\n        private Light? _light;\n        private Material? _material;\n        private float _intensity;\n        private float _emission;\n        private float _stutter;\n        private float _next;\n\n        protected override void Start()\n        {\n            _light = GetComponent<Light>();\n            _material = GetComponent<MeshRenderer>()?.Material;\n            _intensity = _light?.Intensity ?? 0f;\n            _emission = _material?.EmissionStrength ?? 0f;\n            _next = Random.Shared.NextSingle() * Seconds;\n        }\n\n        protected override void Update()\n        {\n            float brightness = Style == FlickerStyle.Blink ? Blink() : Buzz();\n            if (_light != null) _light.Intensity = _intensity * brightness;\n            if (_material != null) _material.EmissionStrength = _emission * brightness;\n        }\n\n        private float Blink()\n        {\n            float t = Time.TotalTime % MathF.Max(Seconds, 0.1f) / MathF.Max(Seconds, 0.1f);\n            return t < 0.18f ? 1f : Low;\n        }\n\n        // Mostly on; every so often a burst of quick drops for a moment.\n        private float Buzz()\n        {\n            _next -= Time.DeltaTime;\n            if (_next <= 0f)\n            {\n                _stutter = 0.1f + Random.Shared.NextSingle() * 0.5f;\n                _next = Seconds * (0.5f + Random.Shared.NextSingle());\n            }\n\n            if (_stutter <= 0f) return 1f;\n\n            _stutter -= Time.DeltaTime;\n            return Random.Shared.NextSingle() < 0.55f ? Low + Random.Shared.NextSingle() * 0.3f : 1f;\n        }\n    }\n}\n","NeonCity/Assets/Scripts/Flyer.cs":"using System.Numerics;\n\nusing Vertex;\n\nnamespace NeonCity\n{\n    /// <summary>\n    /// A flying car: glides along its forward direction, bobbing gently, and once it's gone <see cref=\"Distance\"/> it starts\n    /// again from where it began, out of sight in the fog.\n    /// </summary>\n    public class Flyer : Component\n    {\n        public float Speed { get; set; } = 18f;\n        public float Distance { get; set; } = 300f;\n\n        /// <summary>How far along it starts, so cars on the same path are spread out.</summary>\n        public float Offset { get; set; }\n\n        private Vector3 _from;\n        private Vector3 _forward;\n\n        protected override void Start()\n        {\n            _from = Transform.Position;\n            _forward = Transform.Forward;\n        }\n\n        protected override void Update()\n        {\n            float along = (Offset + Time.TotalTime * Speed) % MathF.Max(Distance, 1f);\n            float bob = MathF.Sin(Time.TotalTime * 0.9f + Offset) * 0.4f;\n            Transform.Position = _from + _forward * along + new Vector3(0f, bob, 0f);\n        }\n    }\n}\n","NeonCity/Assets/Scripts/Hologram.cs":"using System.Numerics;\n\nusing Vertex;\n\nnamespace NeonCity\n{\n    /// <summary>Turns slowly and floats up and down: a hologram over a doorway.</summary>\n    public class Hologram : Component\n    {\n        /// <summary>Degrees a second it turns.</summary>\n        public float Spin { get; set; } = 35f;\n\n        /// <summary>How far up and down it floats.</summary>\n        public float Bob { get; set; } = 0.12f;\n\n        private Vector3 _home;\n\n        protected override void Start()\n        {\n            _home = Transform.Position;\n        }\n\n        protected override void Update()\n        {\n            Transform.Position = _home + new Vector3(0f, MathF.Sin(Time.TotalTime * 1.3f) * Bob, 0f);\n            Transform.EulerAngles = new Vector3(0f, Time.TotalTime * Spin % 360f, 0f);\n        }\n    }\n}\n","NeonCity/Assets/Scripts/Walker.cs":"using System.Numerics;\n\nusing Vertex;\nusing Vertex.Input;\nusing Vertex.Physics;\n\nnamespace NeonCity\n{\n    /// <summary>\n    /// Walks with WASD (Shift to hurry), jumps with Space and looks around with the mouse. Click in the window to take\n    /// the mouse, Escape to let it go.\n    /// </summary>\n    public class Walker : Component\n    {\n        [Header(\"Moving\")]\n        public float Speed { get; set; } = 3.5f;\n        public float RunSpeed { get; set; } = 7f;\n        public float JumpSpeed { get; set; } = 4.5f;\n        public float Gravity { get; set; } = 18f;\n\n        [Header(\"Looking\")]\n        public float MouseSensitivity { get; set; } = 0.12f;\n\n        /// <summary>The camera's object, under this one: it tips up and down while the whole walker turns left and right.</summary>\n        public GameObject? Head { get; set; }\n\n        private CharacterController? _character;\n        private float _pitch;\n\n        protected override void Start()\n        {\n            _character = GetComponent<CharacterController>();\n            if (Head != null) _pitch = Head.Transform.EulerAngles.X;\n        }\n\n        protected override void Update()\n        {\n            if (_character == null) return;\n\n            if (InputSystem.GetMouseButtonDown(MouseButton.Left)) InputSystem.CursorLocked = true;\n            if (InputSystem.GetKeyDown(Key.Escape)) InputSystem.CursorLocked = false;\n\n            if (InputSystem.CursorLocked) Look();\n            Walk(_character);\n        }\n\n        private void Look()\n        {\n            Vector2 mouse = InputSystem.MouseDelta * MouseSensitivity;\n            Transform.EulerAngles += new Vector3(0f, -mouse.X, 0f);\n            _pitch = Math.Clamp(_pitch - mouse.Y, -85f, 85f);\n            if (Head != null) Head.Transform.EulerAngles = new Vector3(_pitch, 0f, 0f);\n        }\n\n        private void Walk(CharacterController character)\n        {\n            float forward = (InputSystem.GetKey(Key.W) ? 1f : 0f) - (InputSystem.GetKey(Key.S) ? 1f : 0f);\n            float right = (InputSystem.GetKey(Key.D) ? 1f : 0f) - (InputSystem.GetKey(Key.A) ? 1f : 0f);\n            Vector3 move = Transform.Forward * forward + Transform.Right * right;\n            move.Y = 0f;\n            if (move.LengthSquared() > 1f) move = Vector3.Normalize(move);\n            move *= InputSystem.GetKey(Key.ShiftLeft) ? RunSpeed : Speed;\n\n            float rise = character.Velocity.Y;\n            if (character.IsGrounded) rise = InputSystem.GetKey(Key.Space) ? JumpSpeed : -1f;\n            else rise -= Gravity * Time.DeltaTime;\n\n            character.Velocity = new Vector3(move.X, rise, move.Z);\n            character.Move(Time.DeltaTime);\n        }\n    }\n}\n","NeonCity/Builder/CityBuilder.cs":"using System.Numerics;\n\nusing Vertex;\nusing Vertex.Physics;\nusing Vertex.Rendering;\nusing Vertex.Serialization;\n\nnamespace NeonCity.Builder\n{\n    /// <summary>\n    /// Makes the city's scene and textures with the engine's own API: a rainy street at night between tall buildings,\n    /// lit by neon signs, street lamps and windows through volumetric fog, with a night market to walk into. The same\n    /// random numbers every time, so it comes out the same.\n    /// </summary>\n    internal static partial class CityBuilder\n    {\n        private static Random _random = new(11);\n        private static string _assets = \"\";\n\n        public static void Build(string assets)\n        {\n            _assets = assets;\n            _random = new Random(11);\n            Directory.CreateDirectory(Path.Combine(assets, \"Scenes\"));\n            Directory.CreateDirectory(Path.Combine(assets, \"Textures\"));\n            Application.AssetFolders = [assets];\n\n            var scene = new Scene();\n            Scene.Active = scene;\n\n            MakeTextures();\n            MakeMaterials();\n            SetLighting(scene.Lighting);\n\n            Streets();\n            Buildings();\n            NightMarket();\n            StreetLife();\n            Skyline();\n            Sky();\n            Player();\n\n            string path = Path.Combine(assets, \"Scenes\", \"Neon City.scene\");\n            SceneFile.Save(scene, path, assets);\n            Console.WriteLine($\"Wrote {path} ({new FileInfo(path).Length / 1024} KB, {scene.GameObjects.Count} objects).\");\n        }\n\n        // ---------------------------------------------------------------- The night\n\n        private static void SetLighting(Lighting lighting)\n        {\n            // A dark sky, glowing purple low down with the city's light.\n            lighting.Sky = SkyStyle.Gradient;\n            lighting.SkyColor = new Color(0.012f, 0.012f, 0.035f);\n            lighting.HorizonColor = new Color(0.2f, 0.07f, 0.24f);\n            lighting.GroundColor = new Color(0.035f, 0.035f, 0.05f);\n            lighting.CloudCover = 0f;\n            lighting.AmbientIntensity = 0.45f;\n            lighting.FogDensity = 0.006f;\n            lighting.Exposure = 1.25f;\n            lighting.Bloom = 1.3f;\n            lighting.AmbientOcclusion = 1f;\n            lighting.Vignette = 0.35f;\n            lighting.ShadowDistance = 90f;\n\n            lighting.VolumetricFog = true;\n            lighting.VolumetricDensity = 0.03f;\n            lighting.VolumetricColor = new Color(0.86f, 0.88f, 1f);\n            lighting.VolumetricHeight = 16f;\n            lighting.VolumetricFalloff = 0.03f;\n            lighting.VolumetricNoise = 0.55f;\n            lighting.VolumetricWind = new Vector3(0.5f, 0.05f, -0.3f);\n            lighting.VolumetricForwardScattering = 0.55f;\n            lighting.VolumetricAmbient = 0.5f;\n            lighting.VolumetricDistance = 100f;\n        }\n\n        // ---------------------------------------------------------------- Making things\n\n        private static GameObject Group(string name, Transform? parent = null)\n        {\n            var group = new GameObject(name);\n            group.Transform.Parent = parent;\n            return group;\n        }\n\n        /// <summary>A mesh made from <paramref name=\"mesh\"/>, in the world as built; solid to walk into if <paramref name=\"solid\"/>.</summary>\n        private static GameObject Add(string name, MeshBuilder mesh, Material material, Transform? parent, bool solid = false, bool shadows = true)\n        {\n            var gameObject = new GameObject(name);\n            gameObject.Transform.Parent = parent;\n            if (mesh.IsEmpty) return gameObject;\n\n            Mesh built = mesh.Build();\n            gameObject.AddComponent<MeshRenderer>(renderer =>\n            {\n                renderer.Mesh = built;\n                renderer.Material = material;\n                renderer.CastShadows = shadows;\n            });\n            if (solid) gameObject.AddComponent<MeshCollider>().Mesh = built;\n            return gameObject;\n        }\n\n        /// <summary>An object at <paramref name=\"position\"/> showing <paramref name=\"mesh\"/>, built round its own origin.</summary>\n        private static GameObject AddAt(string name, Vector3 position, MeshBuilder mesh, Material material, Transform? parent, bool shadows = true)\n        {\n            GameObject gameObject = Add(name, mesh, material, null, shadows: shadows);\n            gameObject.Transform.Position = position;\n            gameObject.Transform.Parent = parent;\n            return gameObject;\n        }\n\n        /// <summary>A box nobody sees, to keep the walker inside the city.</summary>\n        private static void Wall(Vector3 min, Vector3 max, Transform parent)\n        {\n            var wall = new GameObject(\"Invisible Wall\");\n            wall.Transform.Position = (min + max) * 0.5f;\n            wall.Transform.Parent = parent;\n            wall.AddComponent<BoxCollider>().Size = max - min;\n        }\n\n        private static Light PointLight(string name, Vector3 at, Color color, float intensity, float range, Transform parent, float fog = 1f)\n        {\n            var gameObject = new GameObject(name);\n            gameObject.Transform.Position = at;\n            gameObject.Transform.Parent = parent;\n            return gameObject.AddComponent<Light>(light =>\n            {\n                light.Type = LightType.Point;\n                light.Color = color;\n                light.Intensity = intensity;\n                light.Range = range;\n                light.FogStrength = fog;\n                light.CastShadows = false;\n            });\n        }\n\n        private static Light SpotLight(string name, Vector3 at, Vector3 direction, Color color, float intensity, float range, float angle, Transform parent, float fog = 1f)\n        {\n            var gameObject = new GameObject(name);\n            gameObject.Transform.Position = at;\n            gameObject.Transform.Rotation = Facing(direction);\n            gameObject.Transform.Parent = parent;\n            return gameObject.AddComponent<Light>(light =>\n            {\n                light.Type = LightType.Spot;\n                light.Color = color;\n                light.Intensity = intensity;\n                light.Range = range;\n                light.SpotAngle = angle;\n                light.SpotSoftness = 0.5f;\n                light.FogStrength = fog;\n                light.CastShadows = false;\n            });\n        }\n\n        /// <summary>The turn that points an object's forward (-Z) along <paramref name=\"forward\"/>.</summary>\n        private static Quaternion Facing(Vector3 forward)\n        {\n            Vector3 up = MathF.Abs(Vector3.Normalize(forward).Y) > 0.99f ? Vector3.UnitZ : Vector3.UnitY;\n            return Quaternion.Normalize(Quaternion.CreateFromRotationMatrix(Matrix4x4.CreateWorld(Vector3.Zero, Vector3.Normalize(forward), up)));\n        }\n\n        /// <summary>Words on a wall, readable from in front of it, which is the way <paramref name=\"facing\"/> points.</summary>\n        private static WorldText Text(string text, Vector3 at, Vector3 facing, float size, Color color, Transform parent)\n        {\n            var gameObject = new GameObject(\"Text\");\n            gameObject.Transform.Position = at;\n            gameObject.Transform.Rotation = Facing(-facing);\n            gameObject.Transform.Parent = parent;\n            return gameObject.AddComponent<WorldText>(words =>\n            {\n                words.Text = text;\n                words.Size = size;\n                words.Color = color;\n            });\n        }\n\n        private static float Range(float min, float max) => min + (max - min) * _random.NextSingle();\n\n        private static T Pick<T>(IReadOnlyList<T> from) => from[_random.Next(from.Count)];\n\n        // ---------------------------------------------------------------- Neon\n\n        /// <summary>\n        /// A sign of neon tubes spelling <paramref name=\"text\"/>, across (or down, if <paramref name=\"vertical\"/>) a dark\n        /// panel facing the way <paramref name=\"right\"/> × <paramref name=\"up\"/> points, with a light of its colour in front.\n        /// Two-sided signs stick out from a wall and read from both ways along the street.\n        /// </summary>\n        private static GameObject NeonSign(string name, string text, Vector3 centre, Vector3 right, Vector3 up, Color color, float letterHeight,\n            Transform parent, bool vertical = false, bool twoSided = false, bool panel = true, bool frame = true, float light = 2.5f,\n            FlickerStyle? flicker = null, float glow = 5f)\n        {\n            float s = letterHeight / NeonFont.Height;\n            var strokes = new List<Vector2[]>();\n            float width, height;\n            if (vertical)\n            {\n                float step = letterHeight * 1.35f;\n                width = NeonFont.Width * s;\n                height = text.Length * step - (step - letterHeight);\n                for (int i = 0; i < text.Length; i++)\n                {\n                    var origin = new Vector2(-width * 0.5f, height * 0.5f - letterHeight - i * step);\n                    foreach (Vector2[] stroke in NeonFont.Strokes(text[i])) strokes.Add(stroke.Select(p => origin + p * s).ToArray());\n                }\n            }\n            else\n            {\n                width = NeonFont.LineWidth(text) * s;\n                height = letterHeight;\n                for (int i = 0; i < text.Length; i++)\n                {\n                    var origin = new Vector2(-width * 0.5f + i * NeonFont.Advance * s, -letterHeight * 0.5f);\n                    foreach (Vector2[] stroke in NeonFont.Strokes(text[i])) strokes.Add(stroke.Select(p => origin + p * s).ToArray());\n                }\n            }\n\n            return NeonStrokes(name, strokes, width, height, centre, right, up, color, letterHeight * 0.065f, parent, twoSided, panel, frame, light, flicker, glow);\n        }\n\n        /// <summary>A neon sign of lines given in metres across and up from its middle: see <see cref=\"NeonSign\"/>.</summary>\n        private static GameObject NeonStrokes(string name, List<Vector2[]> strokes, float width, float height, Vector3 centre, Vector3 right, Vector3 up,\n            Color color, float tube, Transform parent, bool twoSided, bool panel, bool frame, float light, FlickerStyle? flicker, float glow)\n        {\n            right = Vector3.Normalize(right);\n            up = Vector3.Normalize(up);\n            Vector3 normal = Vector3.Cross(right, up);\n            tube = MathF.Max(tube, 0.03f);\n            float pad = MathF.Min(height, width) * 0.25f + 0.12f;\n            float depth = 0.14f;\n\n            // Built round the light, which sits a little in front of the sign.\n            Vector3 lightAt = twoSided ? Vector3.Zero : normal * 0.35f;\n            var tubes = new MeshBuilder();\n            void Side(Vector3 sideRight, Vector3 sideNormal)\n            {\n                Vector3 face = sideNormal * (depth * 0.5f + tube) - lightAt;\n                foreach (Vector2[] stroke in strokes)\n                {\n                    for (int i = 0; i + 1 < stroke.Length; i++)\n                    {\n                        Vector3 a = face + sideRight * stroke[i].X + up * stroke[i].Y;\n                        Vector3 b = face + sideRight * stroke[i + 1].X + up * stroke[i + 1].Y;\n                        tubes.Beam(a, b, tube, sideNormal);\n                    }\n                }\n\n                if (!frame) return;\n\n                // A tube round the edge of the panel.\n                float w = width * 0.5f + pad * 0.7f, h = height * 0.5f + pad * 0.7f;\n                Vector3[] corners = [face - sideRight * w - up * h, face + sideRight * w - up * h, face + sideRight * w + up * h, face - sideRight * w + up * h];\n                for (int i = 0; i < 4; i++) tubes.Beam(corners[i], corners[(i + 1) % 4], tube * 0.8f, sideNormal);\n            }\n\n            // The other side mirrors the letters so they read the right way round from there too.\n            Side(right, normal);\n            if (twoSided) Side(-right, -normal);\n\n            GameObject sign = AddAt(name, centre + lightAt, tubes, Glow(color, glow), parent, shadows: false);\n            sign.AddComponent<Light>(l =>\n            {\n                l.Type = LightType.Point;\n                l.Color = color;\n                l.Intensity = light;\n                l.Range = MathF.Max(5f, MathF.Max(width, height) * 1.1f);\n                l.CastShadows = false;\n            });\n            if (flicker is { } style) sign.AddComponent<Flicker>(f => f.Style = style);\n\n            if (panel)\n            {\n                var back = new MeshBuilder();\n                back.Box(-lightAt, right, up, normal, new Vector3(width + pad * 2f, height + pad * 2f, depth));\n                AddAt(\"Panel\", Vector3.Zero, back, _signPanel, sign.Transform);\n            }\n\n            return sign;\n        }\n\n        /// <summary>A column of made-up letters, like the signs in a language the city speaks: a few random lines on a 3 by 3 grid each.</summary>\n        private static GameObject GlyphSign(string name, int count, Vector3 centre, Vector3 right, Vector3 up, Color color, float cell, Transform parent, bool twoSided = false)\n        {\n            var strokes = new List<Vector2[]>();\n            float step = cell * 1.3f;\n            float height = count * step - (step - cell);\n            for (int i = 0; i < count; i++)\n            {\n                var origin = new Vector2(-cell * 0.5f, height * 0.5f - cell - i * step);\n                Vector2 Point(int x, int y) => origin + new Vector2(x, y) * (cell * 0.5f);\n\n                // A frame line or two, and some strokes across, down and slanting.\n                int lines = 3 + _random.Next(3);\n                for (int l = 0; l < lines; l++)\n                {\n                    int kind = _random.Next(4);\n                    int a = _random.Next(3), b = _random.Next(3);\n                    strokes.Add(kind switch\n                    {\n                        0 => [Point(0, a), Point(2, a)],\n                        1 => [Point(a, 0), Point(a, 2)],\n                        2 => [Point(a, b), Point(Math.Min(a + 1, 2), Math.Max(b - 1, 0))],\n                        _ => [Point(0, 2), Point(2, 2), Point(2, a)]\n                    });\n                }\n            }\n\n            return NeonStrokes(name, strokes, cell, height, centre, right, up, color, cell * 0.07f, parent, twoSided, panel: true, frame: true, light: 2f, flicker: null, glow: 4.5f);\n        }\n    }\n}\n","NeonCity/Builder/CityBuilder.Life.cs":"using System.Numerics;\n\nusing Vertex;\nusing Vertex.Physics;\nusing Vertex.Rendering;\n\nnamespace NeonCity.Builder\n{\n    // Lamps, cables, stalls and steam along the street; rain and flying cars over it; the city beyond; the moon; the walker.\n    internal static partial class CityBuilder\n    {\n        private static void StreetLife()\n        {\n            Transform group = Group(\"Street\").Transform;\n            StreetLamps(Group(\"Street Lamps\", group).Transform);\n            Cables(Group(\"Cables\", group).Transform);\n            FoodStall(group, \"Yakitori Stall\", 36f, \"YAKITORI\", _orange);\n            FoodStall(group, \"Takoyaki Stall\", 41f, \"TAKOYAKI\", _pink);\n            VendingMachines(group);\n            Steam(group, new Vector3(1.8f, 0f, 10f));\n            Steam(group, new Vector3(-2.2f, 0f, -52f));\n            Clutter(group);\n            Rain(group);\n            FlyingCars(Group(\"Flying Cars\", group).Transform);\n        }\n\n        /// <summary>Lamps along both pavements, each a pole with an arm out over the road and a cone of light down from it.</summary>\n        private static void StreetLamps(Transform group)\n        {\n            var poles = new MeshBuilder();\n            var heads = new MeshBuilder();\n            float[] west = [52f, 20f, -12f, -46f, -78f], east = [36f, 3f, -22f, -54f, -86f];\n            foreach ((float[] zs, float side) in new[] { (west, -1f), (east, 1f) })\n            {\n                foreach (float z in zs)\n                {\n                    var foot = new Vector3(side * 8.4f, 0.15f, z);\n                    var top = foot + new Vector3(0f, 6.6f, 0f);\n                    var end = top + new Vector3(-side * 2.2f, 0f, 0f);\n                    poles.Beam(foot, top, 0.16f);\n                    poles.Beam(top, end, 0.1f);\n                    poles.Box(foot + new Vector3(0f, 0.3f, 0f), new Vector3(0.35f, 0.6f, 0.35f));\n                    poles.Box(end + new Vector3(0f, -0.08f, 0f), new Vector3(0.7f, 0.18f, 0.32f));\n                    heads.Box(end + new Vector3(0f, -0.18f, 0f), new Vector3(0.6f, 0.03f, 0.24f));\n\n                    // Shining down, leaning a little out over the road.\n                    SpotLight(\"Lamp\", end - new Vector3(0f, 0.25f, 0f), new Vector3(-side * 0.25f, -1f, 0f), new Color(0.75f, 0.85f, 1f), 14f, 13f, 75f, group, fog: 1.4f);\n                }\n            }\n\n            Add(\"Lamp Posts\", poles, _darkMetal, group, solid: true);\n            Add(\"Lamp Glass\", heads, Glow(new Color(0.8f, 0.9f, 1f), 8f), group, shadows: false);\n        }\n\n        /// <summary>Power cables slung across the street between the buildings, sagging, and paper lanterns hung along two.</summary>\n        private static void Cables(Transform group)\n        {\n            var cables = new MeshBuilder();\n            var lanterns = new MeshBuilder();\n            float[] crossings = [58f, 47f, 33f, 22f, 10f, -6f, -18f, -44f, -60f];\n            for (int c = 0; c < crossings.Length; c++)\n            {\n                float z = crossings[c];\n                float height = Range(7.5f, 12f);\n                int strands = 1 + _random.Next(3);\n                for (int s = 0; s < strands; s++)\n                {\n                    var from = new Vector3(-9f, height + s * 0.4f, z + Range(-1.5f, 1.5f));\n                    var to = new Vector3(9f, height + Range(-1f, 1.5f) + s * 0.4f, z + Range(-1.5f, 1.5f));\n                    float sag = Range(0.8f, 1.8f);\n                    Vector3 Point(float t) => Vector3.Lerp(from, to, t) - new Vector3(0f, sag * 4f * t * (1f - t), 0f);\n                    for (int i = 0; i < 10; i++) cables.Beam(Point(i / 10f), Point((i + 1) / 10f), 0.035f);\n\n                    // Lanterns on the first strand of two of the crossings.\n                    if (s == 0 && (c == 1 || c == 4))\n                    {\n                        for (int l = 1; l < 8; l++)\n                        {\n                            Vector3 hang = Point(l / 8f);\n                            cables.Beam(hang, hang - new Vector3(0f, 0.35f, 0f), 0.015f);\n                            lanterns.Box(hang - new Vector3(0f, 0.65f, 0f), new Vector3(0.3f, 0.42f, 0.3f));\n                            lanterns.Box(hang - new Vector3(0f, 0.65f, 0f), new Vector3(0.3f, 0.42f, 0.3f), 45f);\n                        }\n\n                        PointLight(\"Lanterns\", Point(0.5f) - new Vector3(0f, 1f, 0f), new Color(1f, 0.25f, 0.12f), 2.5f, 9f, group, fog: 1.4f);\n                    }\n                }\n            }\n\n            Add(\"Cables\", cables, _darkMetal, group, shadows: false);\n            Add(\"Paper Lanterns\", lanterns, Glow(new Color(1f, 0.22f, 0.1f), 1.6f), group, shadows: false);\n        }\n\n        /// <summary>A street food stall against the wall on the west pavement: a counter under an awning, stools, a grill smoking.</summary>\n        private static void FoodStall(Transform parent, string name, float z, string sign, Color color)\n        {\n            Transform stall = Group(name, parent).Transform;\n            var wood = new MeshBuilder();\n            var metal = new MeshBuilder();\n            const float back = -8.9f, front = -6.6f;\n\n            wood.Span(new Vector3(back, 0.15f, z - 1.6f), new Vector3(front, 1.05f, z + 1.6f));\n            wood.Span(new Vector3(back, 1.05f, z - 1.7f), new Vector3(front + 0.25f, 1.12f, z + 1.7f));\n            metal.Span(new Vector3(back + 0.3f, 1.12f, z - 1.1f), new Vector3(back + 1.3f, 1.3f, z + 1.1f));\n            metal.Beam(new Vector3(front - 0.1f, 0.15f, z - 1.6f), new Vector3(front - 0.1f, 2.75f, z - 1.6f), 0.08f);\n            metal.Beam(new Vector3(front - 0.1f, 0.15f, z + 1.6f), new Vector3(front - 0.1f, 2.75f, z + 1.6f), 0.08f);\n            Add(\"Counter\", wood, _darkWood, stall, solid: true);\n            Add(\"Grill\", metal, _darkMetal, stall);\n\n            // The awning, sloping down towards the road, with a strip of light along its edge.\n            var awning = new MeshBuilder();\n            awning.Box(new Vector3(-7.6f, 2.85f, z), Vector3.UnitX, Vector3.UnitY, Vector3.UnitZ, new Vector3(2.9f, 0.08f, 3.8f));\n            Add(\"Awning\", awning, _redCloth, stall);\n            var edge = new MeshBuilder();\n            edge.Box(new Vector3(-6.15f, 2.76f, z), new Vector3(0.06f, 0.1f, 3.8f));\n            Add(\"Awning Light\", edge, Glow(color, 4f), stall, shadows: false);\n\n            for (int i = -1; i <= 1; i++)\n            {\n                var stool = new MeshBuilder();\n                stool.Beam(new Vector3(-6.1f, 0.15f, z + i * 1f), new Vector3(-6.1f, 0.7f, z + i * 1f), 0.06f);\n                stool.Box(new Vector3(-6.1f, 0.72f, z + i * 1f), new Vector3(0.38f, 0.07f, 0.38f));\n                Add(\"Stool\", stool, _vinyl, stall);\n            }\n\n            PointLight(\"Stall Light\", new Vector3(-7.4f, 2.4f, z), new Color(1f, 0.7f, 0.4f), 2.2f, 6f, stall, fog: 0.8f);\n            Text(sign, new Vector3(-6.12f, 2.55f, z), Vector3.UnitX, 0.32f, color, stall);\n\n            var smoke = new GameObject(\"Smoke\");\n            smoke.Transform.Position = new Vector3(-8f, 1.4f, z);\n            smoke.Transform.Parent = stall;\n            smoke.AddComponent<ParticleSystem>(p =>\n            {\n                p.Rate = 14f;\n                p.Lifetime = new FloatRange(2f, 3.2f);\n                p.Speed = new FloatRange(0.5f, 0.9f);\n                p.Spread = 18f;\n                p.Size = new FloatRange(0.35f, 0.6f);\n                p.EndSize = 3.5f;\n                p.StartColor = new Color(0.55f, 0.55f, 0.6f, 0.22f);\n                p.EndColor = new Color(0.4f, 0.4f, 0.45f, 0f);\n                p.Blend = ParticleBlend.Alpha;\n                p.Area = new Vector3(0.8f, 0f, 1.6f);\n            });\n        }\n\n        private static void VendingMachines(Transform parent)\n        {\n            Transform group = Group(\"Vending Machines\", parent).Transform;\n            var bodies = new MeshBuilder();\n            var fronts = new MeshBuilder();\n            for (int i = 0; i < 3; i++)\n            {\n                float z = 43f + i * 1.15f;\n                bodies.Span(new Vector3(8.15f, 0.15f, z - 0.55f), new Vector3(8.95f, 2.05f, z + 0.55f));\n                fronts.Panel(new Vector3(8.14f, 1.25f, z), -Vector3.UnitX, Vector3.UnitY, 0.9f, 1.5f);\n            }\n\n            Add(\"Machines\", bodies, Lit(new Color(0.75f, 0.1f, 0.12f), 0.35f), group, solid: true);\n            Add(\"Fronts\", fronts, Picture(_vending, Color.White), group, shadows: false);\n            PointLight(\"Machine Glow\", new Vector3(7.4f, 1.3f, 44.15f), new Color(0.7f, 0.85f, 1f), 1.5f, 4.5f, group, fog: 0.8f);\n        }\n\n        /// <summary>Steam rising from a grate in the road, thickening the fog round it.</summary>\n        private static void Steam(Transform parent, Vector3 at)\n        {\n            var grate = new MeshBuilder();\n            grate.Box(at + new Vector3(0f, 0.01f, 0f), new Vector3(1f, 0.03f, 1f));\n            GameObject steam = Add(\"Steam Grate\", grate, _darkMetal, parent, shadows: false);\n\n            var rising = new GameObject(\"Steam\");\n            rising.Transform.Position = at + new Vector3(0f, 0.1f, 0f);\n            rising.Transform.Parent = steam.Transform;\n            rising.AddComponent<ParticleSystem>(p =>\n            {\n                p.Rate = 10f;\n                p.Lifetime = new FloatRange(2.5f, 4f);\n                p.Speed = new FloatRange(0.7f, 1.3f);\n                p.Spread = 12f;\n                p.Size = new FloatRange(0.5f, 0.8f);\n                p.EndSize = 4f;\n                p.StartColor = new Color(0.6f, 0.62f, 0.68f, 0.25f);\n                p.EndColor = new Color(0.5f, 0.5f, 0.55f, 0f);\n                p.Blend = ParticleBlend.Alpha;\n                p.Area = new Vector3(0.7f, 0f, 0.7f);\n            });\n\n            var mist = new GameObject(\"Mist\");\n            mist.Transform.Position = at + new Vector3(0f, 2f, 0f);\n            mist.Transform.Scale = new Vector3(4f, 5f, 4f);\n            mist.Transform.Parent = steam.Transform;\n            mist.AddComponent<FogVolume>(f => { f.Density = 0.12f; f.Softness = 1f; });\n        }\n\n        /// <summary>Crates, bins and pipes along the walls, so they don't look swept.</summary>\n        private static void Clutter(Transform parent)\n        {\n            var junk = new MeshBuilder();\n            var pipes = new MeshBuilder();\n            for (int i = 0; i < 22; i++)\n            {\n                float side = i % 2 == 0 ? -1f : 1f;\n                float z = Range(-90f, 64f);\n                if (side > 0f && z > 3f && z < 31f) continue;   // the night market's front\n                if (z > -38f && z < -26f) continue;             // the cross street\n                var size = new Vector3(Range(0.5f, 1.1f), Range(0.4f, 1f), Range(0.5f, 1.2f));\n                junk.Box(new Vector3(side * (8.85f - size.X * 0.5f), 0.15f + size.Y * 0.5f, z), size, Range(-8f, 8f));\n            }\n\n            // Pipes running up the walls in the gaps between buildings.\n            foreach ((float x, float z) in new[] { (-9.05f, 19f), (-9.05f, 25f), (9.05f, 31f), (9.05f, 2f), (9.05f, -27.5f), (-9.05f, -27.5f) })\n            {\n                pipes.Beam(new Vector3(x, 0.15f, z), new Vector3(x, 26f, z), 0.18f);\n                pipes.Beam(new Vector3(x, 0.15f, z + 0.35f), new Vector3(x, 18f, z + 0.35f), 0.1f);\n            }\n\n            Add(\"Crates\", junk, _darkWood, parent, solid: true);\n            Add(\"Pipes\", pipes, _metal, parent);\n        }\n\n        /// <summary>Rain over the open street: streaks falling the length of it, faint against the dark and bright through the lights.</summary>\n        private static void Rain(Transform parent)\n        {\n            var rain = new GameObject(\"Rain\");\n            rain.Transform.Position = new Vector3(0f, 22f, -40f);\n            rain.Transform.Parent = parent;\n            rain.AddComponent<GpuParticleSystem>(p =>\n            {\n                p.Rate = 4500f;\n                p.MaxParticles = 6500;\n                p.Area = new Vector3(19f, 0f, 210f);\n                p.Direction = -Vector3.UnitY;\n                p.Spread = 3f;\n                p.Speed = new FloatRange(17f, 21f);\n                p.Lifetime = new FloatRange(1.1f, 1.3f);\n                p.Size = 0.022f;\n                p.EndSize = 1f;\n                p.Stretch = 0.035f;\n                p.StartColor = new Color(0.7f, 0.78f, 1f, 0.35f);\n                p.EndColor = new Color(0.7f, 0.78f, 1f, 0.35f);\n                p.Blend = ParticleBlend.Additive;\n            });\n        }\n\n        /// <summary>Cars flying along the street above the signs, headlights cutting through the fog.</summary>\n        private static void FlyingCars(Transform group)\n        {\n            (Vector3 Start, float Direction, float Speed, float Offset, Color Glow)[] cars =\n            [\n                (new Vector3(-2.5f, 24f, -170f), 1f, 16f, 0f, _cyan),\n                (new Vector3(3f, 30f, 140f), -1f, 21f, 90f, _pink),\n                (new Vector3(-1f, 41f, 140f), -1f, 13f, 200f, _orange),\n                (new Vector3(1.5f, 35f, -170f), 1f, 24f, 140f, _purple)\n            ];\n\n            foreach ((Vector3 start, float direction, float speed, float offset, Color glow) in cars)\n            {\n                var car = new GameObject(\"Flying Car\");\n                car.Transform.Position = start;\n                car.Transform.Rotation = Facing(new Vector3(0f, 0f, -direction));\n                car.Transform.Parent = group;\n                car.AddComponent<Flyer>(f => { f.Speed = speed; f.Distance = 310f; f.Offset = offset; });\n\n                // Built facing -Z, its front, as an object faces before it's turned.\n                var body = new MeshBuilder();\n                body.Box(Vector3.Zero, new Vector3(2.2f, 0.7f, 4.6f));\n                body.Box(new Vector3(0f, 0.55f, 0.3f), new Vector3(1.6f, 0.45f, 2.2f));\n                body.Box(new Vector3(1.25f, -0.1f, 0f), new Vector3(0.4f, 0.4f, 3.4f));\n                body.Box(new Vector3(-1.25f, -0.1f, 0f), new Vector3(0.4f, 0.4f, 3.4f));\n                AddAt(\"Body\", Vector3.Zero, body, _darkMetal, car.Transform);\n\n                var tail = new MeshBuilder();\n                tail.Box(new Vector3(0f, 0.05f, 2.31f), new Vector3(1.9f, 0.1f, 0.05f));\n                AddAt(\"Tail Lights\", Vector3.Zero, tail, Glow(_red, 10f), car.Transform, shadows: false);\n\n                var head = new MeshBuilder();\n                head.Box(new Vector3(0.7f, 0.05f, -2.31f), new Vector3(0.45f, 0.1f, 0.05f));\n                head.Box(new Vector3(-0.7f, 0.05f, -2.31f), new Vector3(0.45f, 0.1f, 0.05f));\n                AddAt(\"Headlights\", Vector3.Zero, head, Glow(new Color(0.9f, 0.95f, 1f), 14f), car.Transform, shadows: false);\n\n                var under = new MeshBuilder();\n                under.Box(new Vector3(0f, -0.36f, 0f), new Vector3(1.6f, 0.03f, 3.6f));\n                AddAt(\"Underglow\", Vector3.Zero, under, Glow(glow, 6f), car.Transform, shadows: false);\n\n                SpotLight(\"Headlight Beam\", new Vector3(0f, 0f, -2.4f), new Vector3(0f, -0.18f, -1f), new Color(0.85f, 0.9f, 1f), 9f, 28f, 26f, car.Transform, fog: 2.5f);\n            }\n        }\n\n        // ---------------------------------------------------------------- The city beyond\n\n        /// <summary>Towers further off on every side, fading into the fog, their windows lit here and there.</summary>\n        private static void Skyline()\n        {\n            Transform group = Group(\"Skyline\").Transform;\n            var shells = new MeshBuilder();\n            var windows = new MeshBuilder();\n            var beacons = new MeshBuilder();\n\n            for (float x = -150f; x <= 150f; x += 26f)\n            {\n                for (float z = -330f; z <= 190f; z += 28f)\n                {\n                    // Leave the streets and the blocks along them clear.\n                    if (MathF.Abs(x) < 70f && z > -170f && z < 100f) continue;\n                    if (_random.NextSingle() < 0.25f) continue;\n\n                    float w = Range(12f, 22f), d = Range(12f, 24f);\n                    float near = MathF.Min(MathF.Abs(x), MathF.Abs(z + 40f));\n                    float h = Range(35f, 90f) + (near > 120f ? Range(20f, 90f) : 0f);\n                    var c = new Vector3(x + Range(-3f, 3f), 0f, z + Range(-3f, 3f));\n                    shells.Span(c - new Vector3(w * 0.5f, 0f, d * 0.5f), c + new Vector3(w * 0.5f, h, d * 0.5f));\n                    if (h > 100f) beacons.Box(c + new Vector3(0f, h + 1.5f, 0f), new Vector3(0.8f, 0.8f, 0.8f));\n\n                    // Only lit windows: from this far off the dark ones are just wall.\n                    Vector3 toCity = Vector3.Normalize(new Vector3(-c.X, 0f, -40f - c.Z));\n                    (Vector3 Corner, Vector3 Along, Vector3 Normal, float Width)[] faces =\n                    [\n                        (c + new Vector3(-w * 0.5f, 0f, -d * 0.5f), Vector3.UnitZ, -Vector3.UnitX, d),\n                        (c + new Vector3(w * 0.5f, 0f, -d * 0.5f), Vector3.UnitZ, Vector3.UnitX, d),\n                        (c + new Vector3(-w * 0.5f, 0f, -d * 0.5f), Vector3.UnitX, -Vector3.UnitZ, w),\n                        (c + new Vector3(-w * 0.5f, 0f, d * 0.5f), Vector3.UnitX, Vector3.UnitZ, w)\n                    ];\n                    foreach ((Vector3 corner, Vector3 along, Vector3 normal, float width) in faces)\n                    {\n                        if (Vector3.Dot(normal, toCity) < -0.2f) continue;\n                        for (float y = 4f; y + 3f < h; y += 4f)\n                        {\n                            for (float a = 2f; a + 1.5f <= width; a += 3.2f)\n                            {\n                                if (_random.NextSingle() > 0.15f) continue;\n                                (Vector2 lo, Vector2 hi) = WindowPicture(_random.Next(_litColors));\n                                windows.Panel(corner + along * a + new Vector3(0f, y + 1.2f, 0f) + normal * 0.05f, normal, Vector3.UnitY, 2.2f, 2.4f, lo, hi);\n                            }\n                        }\n                    }\n                }\n            }\n\n            Add(\"Towers\", shells, _darkWall, group);\n            Add(\"Windows\", windows, _windows, group, shadows: false);\n            Add(\"Warning Lights\", beacons, Glow(_red, 12f), group, shadows: false).AddComponent<Flicker>(f => { f.Style = FlickerStyle.Blink; f.Seconds = 2f; f.Low = 0f; });\n\n            // A giant sign on a far tower, glowing through the haze down the street.\n            GlyphSign(\"Far Tower Sign\", 6, new Vector3(-30f, 70f, -230f), Vector3.UnitX, Vector3.UnitY, _pink, 5f, group);\n        }\n\n        private static void Sky()\n        {\n            // The moon: dim and blue, high enough to shine down between the towers in shafts. It shows more in the fog than on\n            // the ground, for the shafts.\n            var moon = new GameObject(\"Moon\");\n            moon.Transform.EulerAngles = new Vector3(-55f, 200f, 0f);\n            moon.AddComponent<Light>(light =>\n            {\n                light.Type = LightType.Directional;\n                light.Color = new Color(0.55f, 0.65f, 1f);\n                light.Intensity = 0.22f;\n                light.FogStrength = 2.5f;\n            });\n        }\n\n        private static void Player()\n        {\n            var player = new GameObject(\"Player\");\n            player.Transform.Position = new Vector3(0f, 0f, 58f);\n            player.AddComponent<CharacterController>();\n\n            var head = new GameObject(\"Head\");\n            head.Transform.Parent = player.Transform;\n            head.Transform.Position = new Vector3(0f, 1.65f, 0f);\n            head.AddComponent<Camera>(camera =>\n            {\n                camera.FieldOfView = 72f;\n                camera.ClearColor = new Color(0.02f, 0.02f, 0.04f);\n            });\n\n            player.AddComponent<Walker>(walker => walker.Head = head);\n            player.AddComponent<CityHud>();\n        }\n    }\n}\n","NeonCity/Builder/CityBuilder.Market.cs":"using System.Numerics;\n\nusing Vertex;\nusing Vertex.Rendering;\n\nnamespace NeonCity.Builder\n{\n    // The night market: the ground floor of a tower on the east side of the street (x = 9 to 31, z = 4 to 30), open to\n    // walk into. A ramen bar along the back, a dumpling stall, a bar, tables, and arcade machines by the door.\n    internal static partial class CityBuilder\n    {\n        private const float _floor = 0.15f, _ceiling = 5.6f;\n\n        private static void NightMarket()\n        {\n            Transform market = Group(\"Night Market\").Transform;\n            MarketBuilding(market);\n            Transform inside = Group(\"Inside\", market).Transform;\n            RamenBar(Group(\"Ramen Bar\", inside).Transform);\n            DumplingStall(Group(\"Dumpling Stall\", inside).Transform);\n            Bar(Group(\"Bar\", inside).Transform);\n            Tables(Group(\"Tables\", inside).Transform);\n            Arcade(Group(\"Arcade\", inside).Transform);\n            Ceiling(Group(\"Ceiling\", inside).Transform);\n\n            // Clearer air inside than out, but steam hanging over the kitchen.\n            var clear = new GameObject(\"Clearer Air\");\n            clear.Transform.Position = new Vector3(20f, 3f, 17f);\n            clear.Transform.Scale = new Vector3(21.2f, 6f, 25.2f);\n            clear.Transform.Parent = inside;\n            clear.AddComponent<FogVolume>(f => { f.Density = -0.024f; f.Softness = 0.1f; });\n\n            var steam = new GameObject(\"Kitchen Steam\");\n            steam.Transform.Position = new Vector3(20.5f, 3.2f, 28.3f);\n            steam.Transform.Scale = new Vector3(15f, 3.6f, 2.6f);\n            steam.Transform.Parent = inside;\n            steam.AddComponent<FogVolume>(f => { f.Density = 0.09f; f.Softness = 1f; });\n        }\n\n        private static void MarketBuilding(Transform market)\n        {\n            const float top = 42f;\n            var walls = new MeshBuilder();\n            var frames = new MeshBuilder();\n            var windows = new MeshBuilder();\n\n            // The front wall: posts between a doorway and two wide windows, wall under the windows, and over them all.\n            foreach ((float from, float to) in new[] { (4f, 5.5f), (12f, 14f), (20f, 22f), (28.5f, 30f) })\n                walls.Span(new Vector3(9f, 0f, from), new Vector3(9.4f, _ceiling, to));\n            walls.Span(new Vector3(9f, 0f, 5.5f), new Vector3(9.4f, 1f, 12f));\n            walls.Span(new Vector3(9f, 0f, 22f), new Vector3(9.4f, 1f, 28.5f));\n            walls.Span(new Vector3(9f, 3.6f, 5.5f), new Vector3(9.4f, _ceiling, 12f));\n            walls.Span(new Vector3(9f, 3.9f, 14f), new Vector3(9.4f, _ceiling, 20f));\n            walls.Span(new Vector3(9f, 3.6f, 22f), new Vector3(9.4f, _ceiling, 28.5f));\n\n            // The other three walls, the ceiling, and the tower on top.\n            walls.Span(new Vector3(9f, 0f, 29.6f), new Vector3(31f, _ceiling, 30f));\n            walls.Span(new Vector3(9f, 0f, 4f), new Vector3(31f, _ceiling, 4.4f));\n            walls.Span(new Vector3(30.6f, 0f, 4f), new Vector3(31f, _ceiling, 30f));\n            walls.Span(new Vector3(9f, _ceiling, 4f), new Vector3(31f, 6.2f, 30f));\n            walls.Span(new Vector3(9f, 6.2f, 4f), new Vector3(31f, top, 30f));\n            FacadeWindows(windows, 9f, 31f, 4f, 30f, 7.4f, top, -Vector3.UnitX, 0.5f);\n\n            // Frames round the openings, and a bar across each window.\n            foreach ((float from, float to, float low, float high) in new[] { (5.5f, 12f, 1f, 3.6f), (14f, 20f, _floor, 3.9f), (22f, 28.5f, 1f, 3.6f) })\n            {\n                frames.Span(new Vector3(8.95f, high - 0.1f, from), new Vector3(9.45f, high, to));\n                frames.Span(new Vector3(8.95f, low, from), new Vector3(9.45f, low + 0.08f, from + 0.1f));\n                frames.Span(new Vector3(8.95f, low, from), new Vector3(9.45f, high, from + 0.1f));\n                frames.Span(new Vector3(8.95f, low, to - 0.1f), new Vector3(9.45f, high, to));\n                if (low > 0.5f) frames.Span(new Vector3(9.1f, low, from), new Vector3(9.3f, low + 0.08f, to));\n            }\n\n            // A canopy over the door, lit underneath, and the roof's edge.\n            frames.Span(new Vector3(7.4f, 4.15f, 13f), new Vector3(9.4f, 4.35f, 21f));\n            frames.Span(new Vector3(9f, top, 4f), new Vector3(31f, top + 0.9f, 4.3f));\n            frames.Span(new Vector3(9f, top, 29.7f), new Vector3(31f, top + 0.9f, 30f));\n            frames.Span(new Vector3(9f, top, 4f), new Vector3(9.3f, top + 0.9f, 30f));\n            frames.Span(new Vector3(30.7f, top, 4f), new Vector3(31f, top + 0.9f, 30f));\n            var canopyLight = new MeshBuilder();\n            canopyLight.Span(new Vector3(7.5f, 4.1f, 13.2f), new Vector3(7.6f, 4.15f, 20.8f));\n\n            Add(\"Walls\", walls, _wallMaterial, market, solid: true);\n            Add(\"Frames\", frames, _darkMetal, market);\n            Add(\"Windows\", windows, _windows, market, shadows: false);\n            Add(\"Canopy Light\", canopyLight, Glow(new Color(1f, 0.75f, 0.45f), 5f), market, shadows: false);\n\n            NeonSign(\"Night Market Sign\", \"NIGHT MARKET\", new Vector3(8.75f, 5.35f, 17f), Vector3.UnitZ, Vector3.UnitY, _orange, 0.75f, market, light: 3f);\n            GlyphSign(\"Night Market Tower Sign\", 5, new Vector3(7.9f, 12f, 26f), Vector3.UnitX, Vector3.UnitY, _pink, 1.1f, market, twoSided: true);\n\n            // A hologram turning over the doorway: a ring round a diamond.\n            var hologram = new MeshBuilder();\n            const int sides = 20;\n            for (int i = 0; i < sides; i++)\n            {\n                float a = i * MathF.Tau / sides, b = (i + 1) * MathF.Tau / sides;\n                hologram.Beam(new Vector3(MathF.Cos(a), MathF.Sin(a), 0f) * 1.1f, new Vector3(MathF.Cos(b), MathF.Sin(b), 0f) * 1.1f, 0.05f, Vector3.UnitZ);\n            }\n\n            Vector3[] diamond = [new(0f, 0.75f, 0f), new(0.45f, 0f, 0f), new(0f, -0.75f, 0f), new(-0.45f, 0f, 0f)];\n            for (int i = 0; i < 4; i++) hologram.Beam(diamond[i], diamond[(i + 1) % 4], 0.06f, Vector3.UnitZ);\n            AddAt(\"Hologram\", new Vector3(6.6f, 7.6f, 17f), hologram, Glow(_cyan, 6f), market, shadows: false).AddComponent<Hologram>();\n            PointLight(\"Hologram Glow\", new Vector3(6.6f, 7.6f, 17f), _cyan, 1.5f, 6f, market, fog: 1.5f);\n        }\n\n        /// <summary>Along the back wall: a long counter with stools, the kitchen behind it, menus, lamps and the curtain over it all.</summary>\n        private static void RamenBar(Transform group)\n        {\n            var wood = new MeshBuilder { TexturesPerUnit = 0.5f };\n            var top = new MeshBuilder { TexturesPerUnit = 0.5f };\n            var steel = new MeshBuilder();\n            var bowls = new MeshBuilder();\n            var dark = new MeshBuilder();\n\n            wood.Span(new Vector3(13f, _floor, 26.4f), new Vector3(27f, 1f, 27.2f));\n            top.Span(new Vector3(12.9f, 1f, 26.15f), new Vector3(27.1f, 1.08f, 27.45f));\n\n            // The kitchen: a steel counter along the wall, shelves of bowls over it, pots steaming on it.\n            steel.Span(new Vector3(12.5f, _floor, 28.9f), new Vector3(28.5f, 0.95f, 29.6f));\n            for (float y = 1.7f; y < 2.5f; y += 0.6f)\n            {\n                steel.Span(new Vector3(13f, y, 29.25f), new Vector3(28f, y + 0.04f, 29.6f));\n                for (float x = 13.4f; x < 27.8f; x += 0.45f) bowls.Box(new Vector3(x, y + 0.1f, 29.42f), new Vector3(0.3f, 0.14f, 0.3f));\n            }\n\n            foreach (float x in (ReadOnlySpan<float>)[15f, 17.5f, 20f, 22.5f])\n            {\n                dark.Box(new Vector3(x, 1.2f, 29.2f), new Vector3(0.6f, 0.5f, 0.55f));\n            }\n\n            Add(\"Counter\", wood, _darkWood, group, solid: true);\n            Add(\"Counter Top\", top, _woodMaterial, group, solid: true);\n            Add(\"Kitchen\", steel, _steel, group, solid: true);\n            Add(\"Bowls\", bowls, _ceramic, group);\n            Add(\"Pots\", dark, _darkMetal, group);\n\n            // A glowing strip along the foot of the counter.\n            var kick = new MeshBuilder();\n            kick.Span(new Vector3(13f, 0.2f, 26.36f), new Vector3(27f, 0.25f, 26.4f));\n            Add(\"Counter Light\", kick, Glow(new Color(1f, 0.55f, 0.2f), 3f), group, shadows: false);\n\n            var steam = new GameObject(\"Pot Steam\");\n            steam.Transform.Position = new Vector3(18.75f, 1.5f, 29.2f);\n            steam.Transform.Parent = group;\n            steam.AddComponent<ParticleSystem>(p =>\n            {\n                p.Rate = 9f;\n                p.Lifetime = new FloatRange(1.8f, 2.6f);\n                p.Speed = new FloatRange(0.4f, 0.7f);\n                p.Spread = 15f;\n                p.Size = new FloatRange(0.25f, 0.4f);\n                p.EndSize = 3f;\n                p.StartColor = new Color(0.9f, 0.88f, 0.85f, 0.22f);\n                p.EndColor = new Color(0.8f, 0.8f, 0.8f, 0f);\n                p.Blend = ParticleBlend.Alpha;\n                p.Area = new Vector3(8f, 0f, 0.3f);\n            });\n\n            // Stools along the counter.\n            var poles = new MeshBuilder();\n            var seats = new MeshBuilder();\n            for (float x = 14f; x <= 26.1f; x += 2f)\n            {\n                poles.Beam(new Vector3(x, _floor, 25.7f), new Vector3(x, 0.72f, 25.7f), 0.07f);\n                poles.Box(new Vector3(x, _floor + 0.02f, 25.7f), new Vector3(0.4f, 0.04f, 0.4f));\n                seats.Box(new Vector3(x, 0.76f, 25.7f), new Vector3(0.42f, 0.09f, 0.42f));\n            }\n\n            Add(\"Stool Legs\", poles, _steel, group);\n            Add(\"Stool Seats\", seats, _vinyl, group);\n\n            // Short curtains hung over the counter, the shop's name across them.\n            var curtain = new MeshBuilder();\n            for (float x = 13.2f; x < 26.9f; x += 2.25f) curtain.Span(new Vector3(x, 2.35f, 26.25f), new Vector3(x + 2.15f, 3.05f, 26.3f));\n            curtain.Span(new Vector3(13f, 3.05f, 26.2f), new Vector3(27f, 3.1f, 26.35f));\n            Add(\"Curtain\", curtain, _redCloth, group);\n            Text(\"RAMEN  SHOYU  MISO  TONKOTSU\", new Vector3(20f, 2.7f, 26.2f), -Vector3.UnitZ, 0.32f, new Color(1f, 0.95f, 0.85f), group);\n\n            // Menus on the wall over the kitchen, lit from behind.\n            var boards = new MeshBuilder();\n            var backlight = new MeshBuilder();\n            string[][] menus =\n            [\n                [\"SHOYU RAMEN   850\", \"MISO RAMEN    900\", \"TONKOTSU      980\"],\n                [\"GYOZA (6)     450\", \"KARAAGE       520\", \"RICE          200\"],\n                [\"BEER          600\", \"HIGHBALL      550\", \"GREEN TEA     150\"]\n            ];\n            for (int i = 0; i < menus.Length; i++)\n            {\n                float x = 15.5f + i * 4.5f;\n                boards.Span(new Vector3(x - 1.9f, 3.25f, 29.5f), new Vector3(x + 1.9f, 4.65f, 29.58f));\n                backlight.Span(new Vector3(x - 2f, 3.15f, 29.58f), new Vector3(x + 2f, 4.75f, 29.6f));\n                for (int line = 0; line < menus[i].Length; line++)\n                    Text(menus[i][line], new Vector3(x, 4.35f - line * 0.42f, 29.48f), -Vector3.UnitZ, 0.26f, new Color(1f, 0.9f, 0.7f), group);\n            }\n\n            Add(\"Menu Boards\", boards, _signPanel, group);\n            Add(\"Menu Backlight\", backlight, Glow(new Color(1f, 0.7f, 0.35f), 2f), group, shadows: false);\n\n            // Lamps hung low over the counter.\n            Lamps(group, [new Vector3(16f, 3.3f, 26.8f), new Vector3(20f, 3.3f, 26.8f), new Vector3(24f, 3.3f, 26.8f)], new Color(1f, 0.68f, 0.38f), 5f, 6f);\n        }\n\n        /// <summary>Lamps hanging from the ceiling on cords, each with a shade glowing underneath and a warm light.</summary>\n        private static void Lamps(Transform group, Vector3[] at, Color color, float intensity, float range)\n        {\n            var cords = new MeshBuilder();\n            var shades = new MeshBuilder();\n            var bulbs = new MeshBuilder();\n            foreach (Vector3 p in at)\n            {\n                cords.Beam(new Vector3(p.X, _ceiling, p.Z), p + new Vector3(0f, 0.2f, 0f), 0.02f);\n                shades.Box(p + new Vector3(0f, 0.1f, 0f), new Vector3(0.5f, 0.22f, 0.5f));\n                bulbs.Box(p - new Vector3(0f, 0.02f, 0f), new Vector3(0.36f, 0.03f, 0.36f));\n                PointLight(\"Lamp\", p - new Vector3(0f, 0.25f, 0f), color, intensity, range, group, fog: 0.6f);\n            }\n\n            Add(\"Lamp Cords\", cords, _darkMetal, group, shadows: false);\n            Add(\"Lamp Shades\", shades, _darkMetal, group, shadows: false);\n            Add(\"Lamp Bulbs\", bulbs, Glow(color, 6f), group, shadows: false);\n        }\n\n        /// <summary>Against the far wall: a counter of steamer baskets, a glowing drinks fridge, and a green sign.</summary>\n        private static void DumplingStall(Transform group)\n        {\n            var counter = new MeshBuilder { TexturesPerUnit = 0.5f };\n            var baskets = new MeshBuilder();\n            counter.Span(new Vector3(28.4f, _floor, 9f), new Vector3(29.3f, 1.05f, 21f));\n            counter.Span(new Vector3(28.3f, 1.05f, 8.9f), new Vector3(29.4f, 1.12f, 21.1f));\n            for (float z = 10f; z < 20.5f; z += 1.4f)\n            {\n                baskets.Box(new Vector3(28.85f, 1.22f, z), new Vector3(0.55f, 0.2f, 0.55f));\n                baskets.Box(new Vector3(28.85f, 1.42f, z), new Vector3(0.5f, 0.18f, 0.5f));\n            }\n\n            Add(\"Counter\", counter, _darkWood, group, solid: true);\n            Add(\"Steamer Baskets\", baskets, Lit(new Color(0.75f, 0.6f, 0.35f), 0.8f), group);\n\n            var fridge = new MeshBuilder();\n            fridge.Span(new Vector3(29.7f, _floor, 22.2f), new Vector3(30.6f, 2.3f, 24.4f));\n            Add(\"Fridge\", fridge, _steel, group, solid: true);\n            var door = new MeshBuilder();\n            door.Panel(new Vector3(29.69f, 1.25f, 23.3f), -Vector3.UnitX, Vector3.UnitY, 2f, 1.9f);\n            Add(\"Fridge Door\", door, Picture(_vending, new Color(0.85f, 0.95f, 1f)), group, shadows: false);\n            PointLight(\"Fridge Glow\", new Vector3(29f, 1.4f, 23.3f), new Color(0.6f, 0.85f, 1f), 1.2f, 4f, group, fog: 0.5f);\n\n            NeonSign(\"Gyoza Sign\", \"GYOZA\", new Vector3(30.45f, 3.4f, 15f), Vector3.UnitZ, Vector3.UnitY, _green, 0.7f, group, light: 2f);\n            Lamps(group, [new Vector3(28.85f, 3.1f, 12f), new Vector3(28.85f, 3.1f, 18f)], new Color(1f, 0.72f, 0.45f), 4f, 5.5f);\n        }\n\n        /// <summary>In the corner by the front: a bar, bottles glowing on shelves behind it, a blue sign.</summary>\n        private static void Bar(Transform group)\n        {\n            var counter = new MeshBuilder { TexturesPerUnit = 0.5f };\n            counter.Span(new Vector3(20f, _floor, 5.6f), new Vector3(29f, 1.1f, 6.4f));\n            counter.Span(new Vector3(19.9f, 1.1f, 5.5f), new Vector3(29.1f, 1.18f, 6.6f));\n            Add(\"Bar Counter\", counter, _darkWood, group, solid: true);\n\n            var shelves = new MeshBuilder();\n            Color[] bottleColors = [new(1f, 0.6f, 0.15f), new(0.3f, 1f, 0.5f), new(0.4f, 0.6f, 1f)];\n            var bottles = bottleColors.Select(_ => new MeshBuilder()).ToArray();\n            for (float y = 1.4f; y < 2.9f; y += 0.55f)\n            {\n                shelves.Span(new Vector3(20.5f, y, 4.4f), new Vector3(29f, y + 0.04f, 4.8f));\n                for (float x = 20.7f; x < 28.8f; x += Range(0.15f, 0.3f))\n                {\n                    float h = Range(0.22f, 0.36f);\n                    bottles[_random.Next(bottles.Length)].Box(new Vector3(x, y + 0.04f + h * 0.5f, 4.6f), new Vector3(0.08f, h, 0.08f));\n                }\n            }\n\n            Add(\"Shelves\", shelves, _darkMetal, group);\n            for (int i = 0; i < bottles.Length; i++) Add(\"Bottles\", bottles[i], Glow(bottleColors[i], 1.6f), group, shadows: false);\n\n            var poles = new MeshBuilder();\n            var seats = new MeshBuilder();\n            for (float x = 21f; x < 28.6f; x += 1.5f)\n            {\n                poles.Beam(new Vector3(x, _floor, 7.2f), new Vector3(x, 0.8f, 7.2f), 0.07f);\n                seats.Box(new Vector3(x, 0.84f, 7.2f), new Vector3(0.42f, 0.09f, 0.42f));\n            }\n\n            Add(\"Bar Stool Legs\", poles, _steel, group);\n            Add(\"Bar Stool Seats\", seats, Lit(new Color(0.15f, 0.12f, 0.35f), 0.4f), group);\n\n            NeonSign(\"Bar Sign\", \"BAR\", new Vector3(24.8f, 3.7f, 4.55f), Vector3.UnitX, Vector3.UnitY, _blue, 0.8f, group, light: 2.2f);\n            PointLight(\"Bar Light\", new Vector3(24.5f, 3f, 8f), _purple, 2.5f, 8f, group, fog: 0.6f);\n        }\n\n        /// <summary>Tables in the middle, each with four stools and a lamp over it.</summary>\n        private static void Tables(Transform group)\n        {\n            var tops = new MeshBuilder { TexturesPerUnit = 0.5f };\n            var legs = new MeshBuilder();\n            var seats = new MeshBuilder();\n            Vector3[] centres = [new(15.5f, 0f, 10.5f), new(21.5f, 0f, 12f), new(15.5f, 0f, 22.5f), new(21.5f, 0f, 21.5f)];\n            foreach (Vector3 c in centres)\n            {\n                tops.Box(c + new Vector3(0f, 0.79f, 0f), new Vector3(1.3f, 0.06f, 1.3f));\n                legs.Beam(c + new Vector3(0f, _floor, 0f), c + new Vector3(0f, 0.76f, 0f), 0.1f);\n                legs.Box(c + new Vector3(0f, _floor + 0.02f, 0f), new Vector3(0.6f, 0.04f, 0.6f));\n                foreach (Vector3 side in (ReadOnlySpan<Vector3>)[Vector3.UnitX, -Vector3.UnitX, Vector3.UnitZ, -Vector3.UnitZ])\n                {\n                    Vector3 s = c + side * 1f;\n                    legs.Beam(s + new Vector3(0f, _floor, 0f), s + new Vector3(0f, 0.45f, 0f), 0.05f);\n                    seats.Box(s + new Vector3(0f, 0.48f, 0f), new Vector3(0.36f, 0.06f, 0.36f));\n                }\n            }\n\n            Add(\"Table Tops\", tops, _woodMaterial, group, solid: true);\n            Add(\"Legs\", legs, _darkMetal, group);\n            Add(\"Stools\", seats, _vinyl, group);\n            Lamps(group, centres.Select(c => c + new Vector3(0f, 2.7f, 0f)).ToArray(), new Color(1f, 0.7f, 0.45f), 3.5f, 5.5f);\n        }\n\n        /// <summary>Three arcade machines against the front wall, their screens glowing.</summary>\n        private static void Arcade(Transform group)\n        {\n            var bodies = new MeshBuilder();\n            var screens = new MeshBuilder();\n            Color[] marquees = [_pink, _cyan, _gold];\n            for (int i = 0; i < 3; i++)\n            {\n                float x = 11.2f + i * 1.4f;\n                bodies.Span(new Vector3(x - 0.55f, _floor, 4.4f), new Vector3(x + 0.55f, 1.95f, 5.3f));\n                bodies.Span(new Vector3(x - 0.55f, 0.9f, 5.3f), new Vector3(x + 0.55f, 1.0f, 5.7f));\n                float u = i / 3f;\n                screens.Panel(new Vector3(x, 1.4f, 5.31f), Vector3.UnitZ, Vector3.UnitY, 0.8f, 0.65f, new Vector2(u, 0f), new Vector2(u + 0.6f, 0.8f));\n\n                var marquee = new MeshBuilder();\n                marquee.Span(new Vector3(x - 0.5f, 1.75f, 5.3f), new Vector3(x + 0.5f, 1.92f, 5.33f));\n                Add(\"Marquee\", marquee, Glow(marquees[i], 4f), group, shadows: false);\n            }\n\n            Add(\"Cabinets\", bodies, Lit(new Color(0.06f, 0.05f, 0.1f), 0.4f), group, solid: true);\n            Add(\"Screens\", screens, Picture(_screens, new Color(1.2f, 1.2f, 1.2f)), group, shadows: false);\n            PointLight(\"Screen Glow\", new Vector3(12.6f, 1.5f, 6.4f), new Color(0.6f, 0.4f, 1f), 1.4f, 4.5f, group, fog: 0.5f);\n            Text(\"INSERT COIN\", new Vector3(12.6f, 2.25f, 5.36f), Vector3.UnitZ, 0.22f, _gold, group);\n        }\n\n        /// <summary>The floor, panelling round the walls, pipes across the ceiling and strips of light between them.</summary>\n        private static void Ceiling(Transform group)\n        {\n            var floor = new MeshBuilder { TexturesPerUnit = 0.5f };\n            floor.Span(new Vector3(9.4f, 0f, 4.4f), new Vector3(30.6f, _floor, 29.6f));\n            floor.Span(new Vector3(9f, 0f, 14f), new Vector3(9.4f, _floor, 20f));\n            Add(\"Floor\", floor, _floorTiles, group, solid: true, shadows: false);\n\n            var panels = new MeshBuilder { TexturesPerUnit = 0.5f };\n            panels.Span(new Vector3(9.4f, _floor, 29.54f), new Vector3(30.6f, 1.1f, 29.6f));\n            panels.Span(new Vector3(9.4f, _floor, 4.4f), new Vector3(30.6f, 1.1f, 4.46f));\n            panels.Span(new Vector3(30.54f, _floor, 4.4f), new Vector3(30.6f, 1.1f, 29.6f));\n            Add(\"Panelling\", panels, _darkWood, group, shadows: false);\n\n            var plaster = new MeshBuilder();\n            plaster.Span(new Vector3(9.4f, 1.1f, 29.57f), new Vector3(30.6f, _ceiling, 29.6f));\n            plaster.Span(new Vector3(9.4f, 1.1f, 4.4f), new Vector3(30.6f, _ceiling, 4.43f));\n            plaster.Span(new Vector3(30.57f, 1.1f, 4.4f), new Vector3(30.6f, _ceiling, 29.6f));\n            Add(\"Plaster\", plaster, _plaster, group, shadows: false);\n\n            var pipes = new MeshBuilder();\n            foreach ((float z, float y, float thick) in new[] { (8f, 5.3f, 0.22f), (8.4f, 5.35f, 0.12f), (25f, 5.3f, 0.25f), (14f, 5.42f, 0.1f) })\n                pipes.Beam(new Vector3(9.4f, y, z), new Vector3(30.6f, y, z), thick);\n            Add(\"Pipes\", pipes, _metal, group, shadows: false);\n\n            var strips = new MeshBuilder();\n            foreach (float z in (ReadOnlySpan<float>)[11f, 17f, 23f])\n                strips.Span(new Vector3(11f, _ceiling - 0.05f, z - 0.06f), new Vector3(29f, _ceiling, z + 0.06f));\n            Add(\"Light Strips\", strips, Glow(new Color(0.7f, 0.82f, 1f), 2f), group, shadows: false);\n\n            PointLight(\"Ceiling Light\", new Vector3(14f, 5f, 17f), new Color(0.95f, 0.88f, 0.8f), 2.2f, 13f, group, fog: 0.3f);\n            PointLight(\"Ceiling Light\", new Vector3(25f, 5f, 17f), new Color(0.95f, 0.88f, 0.8f), 2.2f, 13f, group, fog: 0.3f);\n        }\n    }\n}\n","NeonCity/Builder/CityBuilder.Materials.cs":"using System.Numerics;\n\nusing Vertex;\nusing Vertex.Rendering;\n\nnamespace NeonCity.Builder\n{\n    // The textures, made from noise and saved as PNG files next to the scene, and the materials everything's made of.\n    internal static partial class CityBuilder\n    {\n        private static Texture _concrete = null!, _asphalt = null!, _tiles = null!, _palette = null!, _advert = null!, _screens = null!,\n            _wood = null!, _vending = null!;\n\n        private static Material _wallMaterial = null!, _darkWall = null!, _metal = null!, _darkMetal = null!, _glass = null!, _road = null!,\n            _sidewalk = null!, _puddle = null!, _marking = null!, _windows = null!, _signPanel = null!, _woodMaterial = null!, _darkWood = null!,\n            _steel = null!, _redCloth = null!, _vinyl = null!, _floorTiles = null!, _plaster = null!, _ceramic = null!, _ground = null!;\n\n        /// <summary>\n        /// The window colours, each a window picture in the windows texture, which every window shows one of: lit ones first,\n        /// warm, cool and a few coloured by signs and screens inside; then dark ones.\n        /// </summary>\n        private static readonly Color[] _windowColors =\n        [\n            new(1f, 0.74f, 0.42f), new(0.95f, 0.66f, 0.36f), new(1f, 0.84f, 0.6f), new(0.66f, 0.8f, 1f), new(0.5f, 0.7f, 1f),\n            new(0.3f, 0.95f, 0.9f), new(1f, 0.42f, 0.78f), new(0.7f, 0.45f, 1f), new(0.5f, 0.36f, 0.22f), new(0.4f, 0.5f, 0.7f),\n            new(0.05f, 0.06f, 0.08f), new(0.04f, 0.05f, 0.07f), new(0.07f, 0.07f, 0.09f), new(0.05f, 0.07f, 0.12f), new(0.08f, 0.06f, 0.07f),\n            new(0.03f, 0.04f, 0.05f)\n        ];\n\n        private const int _litColors = 10;\n\n        private static void MakeTextures()\n        {\n            _concrete = SaveTexture(\"Concrete\", 256, 256, (x, y) =>\n            {\n                // Weathered panels: blotchy, with seams between them and streaks of dirt running down from each seam.\n                float n = Layered(x / 32f, y / 32f, 8) * 0.6f + Layered(x / 8f, y / 8f, 32) * 0.25f;\n                float seam = (y % 128 < 2 || x % 128 < 2) ? 0.55f : 1f;\n                float streak = 1f - 0.25f * MathF.Exp(-(y % 128) / 40f) * Layered(x / 4f, 0f, 64);\n                return Grey((0.55f + n * 0.45f) * seam * streak);\n            });\n\n            _asphalt = SaveTexture(\"Asphalt\", 256, 256, (x, y) =>\n            {\n                float n = Layered(x / 4f, y / 4f, 64) * 0.5f + Layered(x / 32f, y / 32f, 8) * 0.5f;\n                float speck = Hash(x, y, 256) > 0.93f ? 0.25f : 0f;\n                return Grey(0.4f + n * 0.5f + speck);\n            });\n\n            _tiles = SaveTexture(\"Tiles\", 256, 256, (x, y) =>\n            {\n                // Square tiles, each a slightly different shade, with dark grout between.\n                bool grout = x % 64 < 3 || y % 64 < 3;\n                float shade = 0.8f + Hash(x / 64, y / 64, 4) * 0.2f + Layered(x / 16f, y / 16f, 16) * 0.08f;\n                return Grey(grout ? 0.25f : shade);\n            });\n\n            _wood = SaveTexture(\"Wood\", 256, 256, (x, y) =>\n            {\n                // Planks along x, with grain.\n                int plank = y / 32;\n                float grain = MathF.Sin((x + Hash(plank, 0, 64) * 300f) * (MathF.Tau * 8f / 256f) + Layered(x / 32f, y / 4f, 8) * 6f) * 0.5f + 0.5f;\n                float shade = 0.7f + grain * 0.25f + Hash(plank, 1, 64) * 0.1f;\n                if (y % 32 < 1) shade *= 0.5f;\n                return new Color(shade, shade * 0.82f, shade * 0.66f);\n            });\n\n            _palette = SaveTexture(\"Windows\", _windowColors.Length * _windowCell, _windowCell, (x, y) =>\n            {\n                // A window of each colour side by side: a frame and a bar down the middle, blinds part way down lit\n                // ones, which are brighter lower down where the room's lamps are; a pale streak of reflection on dark ones.\n                int index = x / _windowCell, lx = x % _windowCell;\n                Color color = _windowColors[index];\n                bool frame = lx < 2 || lx >= _windowCell - 2 || y < 2 || y >= _windowCell - 2 || lx == _windowCell / 2 || lx == _windowCell / 2 - 1;\n                if (frame) return new Color(0.03f, 0.03f, 0.035f);\n\n                if (index < _litColors)\n                {\n                    float shade = 0.7f + 0.3f * y / _windowCell;\n                    if (y < 12 && y % 3 == 0) shade *= 0.55f;\n                    return color * shade;\n                }\n\n                float streak = MathF.Abs(lx - y * 0.6f - 4f) < 2f ? 0.06f : 0f;\n                return new Color(color.R + streak, color.G + streak, color.B + streak * 1.3f);\n            });\n\n            _advert = SaveTexture(\"Advert\", 128, 256, (x, y) =>\n            {\n                // A face in profile isn't something noise can draw, so: a sunset of bands behind a big ring and stripes,\n                // the kind of thing that sells a drink. White, so the colour comes from the material it's tinted by.\n                float u = x / 128f, v = y / 256f;\n                float bands = 0.35f + 0.65f * (1f - v);\n                float ring = MathF.Abs(MathF.Sqrt((u - 0.5f) * (u - 0.5f) * 4f + (v - 0.38f) * (v - 0.38f) * 16f) - 0.8f) < 0.08f ? 1f : 0f;\n                float stripes = v > 0.62f && v < 0.9f && (int)(v * 40f) % 2 == 0 ? 0.9f : 0f;\n                float scan = (y % 4 == 0) ? 0.75f : 1f;\n                float value = MathF.Max(MathF.Max(bands * 0.45f, ring), stripes) * scan;\n                return Grey(value);\n            });\n\n            _screens = SaveTexture(\"Screens\", 64, 64, (x, y) =>\n            {\n                // Chunky game pixels: a dark sky, a row of blocks, a little ship.\n                int px = x / 4, py = y / 4;\n                Color sky = new(0.05f, 0.02f + py * 0.012f, 0.18f);\n                if (py > 12) return new Color(0.2f, 0.9f, 0.4f);\n                if (py == 2 && px % 3 != 0) return new Color(1f, 0.3f, 0.6f);\n                if (py == 4 && px % 4 == 1) return new Color(1f, 0.85f, 0.2f);\n                if (py >= 9 && py <= 10 && px >= 7 && px <= 9) return new Color(0.4f, 0.85f, 1f);\n                return Hash(px, py, 16) > 0.95f ? new Color(0.9f, 0.9f, 1f) : sky;\n            });\n\n            _vending = SaveTexture(\"Vending\", 64, 128, (x, y) =>\n            {\n                // Rows of brightly coloured cans behind glass, with a lit panel along the top.\n                if (y < 18) return new Color(0.95f, 0.95f, 1f);\n                int column = x / 12, row = (y - 18) / 18;\n                bool can = x % 12 > 2 && x % 12 < 10 && (y - 18) % 18 > 3 && (y - 18) % 18 < 15 && column < 5;\n                if (!can) return new Color(0.75f, 0.85f, 0.95f);\n                Color[] cans = [new(1f, 0.2f, 0.2f), new(0.2f, 0.6f, 1f), new(1f, 0.8f, 0.1f), new(0.3f, 0.9f, 0.4f), new(1f, 0.4f, 0.8f)];\n                return cans[(column + row) % cans.Length];\n            });\n        }\n\n        private static void MakeMaterials()\n        {\n            _wallMaterial = Lit(new Color(0.34f, 0.33f, 0.35f), 0.85f, texture: _concrete);\n            _darkWall = Lit(new Color(0.16f, 0.16f, 0.18f), 0.8f, texture: _concrete);\n            _metal = Lit(new Color(0.35f, 0.36f, 0.38f), 0.45f, metallic: 0.8f);\n            _darkMetal = Lit(new Color(0.07f, 0.07f, 0.08f), 0.4f, metallic: 0.6f);\n            _glass = Lit(new Color(0.015f, 0.02f, 0.03f), 0.06f, metallic: 0.3f);\n            _road = Lit(new Color(0.2f, 0.2f, 0.22f), 0.3f, texture: _asphalt);\n            _sidewalk = Lit(new Color(0.3f, 0.3f, 0.32f), 0.45f, texture: _tiles);\n            _puddle = Lit(new Color(0.05f, 0.05f, 0.06f), 0.06f);\n            _marking = Lit(new Color(0.75f, 0.72f, 0.6f), 0.5f);\n            _signPanel = Lit(new Color(0.04f, 0.04f, 0.05f), 0.5f, metallic: 0.4f);\n            _woodMaterial = Lit(new Color(0.75f, 0.6f, 0.45f), 0.55f, texture: _wood);\n            _darkWood = Lit(new Color(0.3f, 0.18f, 0.12f), 0.5f, texture: _wood);\n            _steel = Lit(new Color(0.62f, 0.64f, 0.67f), 0.3f, metallic: 0.9f);\n            _redCloth = Lit(new Color(0.6f, 0.06f, 0.07f), 0.9f);\n            _vinyl = Lit(new Color(0.65f, 0.08f, 0.1f), 0.35f);\n            _floorTiles = Lit(new Color(0.42f, 0.4f, 0.38f), 0.22f, texture: _tiles);\n            _plaster = Lit(new Color(0.3f, 0.26f, 0.24f), 0.85f, texture: _concrete);\n            _ceramic = Lit(new Color(0.9f, 0.88f, 0.84f), 0.25f);\n            _ground = Lit(new Color(0.08f, 0.08f, 0.09f), 0.6f, texture: _asphalt);\n\n            // Windows light themselves: each takes its colour from the palette, a little dimmer than full.\n            _windows = new Material { Shading = ShadingModel.Unlit, Color = new Color(0.62f, 0.62f, 0.62f), Texture = _palette };\n        }\n\n        private static Material Lit(Color color, float roughness, float metallic = 0f, Texture? texture = null) =>\n            new() { Color = color, Roughness = roughness, Metallic = metallic, Texture = texture };\n\n        /// <summary>Glowing, like a neon tube: dark itself, but giving off its colour brightly enough to bloom.</summary>\n        private static Material Glow(Color color, float strength) =>\n            new() { Color = new Color(0.05f, 0.05f, 0.05f), Roughness = 0.3f, Emission = color, EmissionStrength = strength };\n\n        private static Material Picture(Texture texture, Color tint) =>\n            new() { Shading = ShadingModel.Unlit, Color = tint, Texture = texture };\n\n        /// <summary>The corners of window picture <paramref name=\"index\"/> in the windows texture (see <see cref=\"_windowColors\"/>).</summary>\n        private static (Vector2 Min, Vector2 Max) WindowPicture(int index) =>\n            (new Vector2((index * _windowCell + 0.5f) / (_windowColors.Length * _windowCell), 0f),\n             new Vector2(((index + 1) * _windowCell - 0.5f) / (_windowColors.Length * _windowCell), 1f));\n\n        private const int _windowCell = 32;\n\n        private static Texture SaveTexture(string name, int width, int height, Func<int, int, Color> pixel)\n        {\n            var rgba = new byte[width * height * 4];\n            for (int y = 0; y < height; y++)\n            {\n                for (int x = 0; x < width; x++)\n                {\n                    Color c = pixel(x, y);\n                    int i = (y * width + x) * 4;\n                    rgba[i] = (byte)Math.Clamp(c.R * 255f, 0f, 255f);\n                    rgba[i + 1] = (byte)Math.Clamp(c.G * 255f, 0f, 255f);\n                    rgba[i + 2] = (byte)Math.Clamp(c.B * 255f, 0f, 255f);\n                    rgba[i + 3] = 255;\n                }\n            }\n\n            string path = Path.Combine(_assets, \"Textures\", name + \".png\");\n            Png.Save(path, width, height, rgba);\n            return Assets.LoadTexture(path);\n        }\n\n        private static Color Grey(float value) => new(value, value, value);\n\n        // ---------------------------------------------------------------- Noise that tiles\n\n        private static float Hash(int x, int y, int period)\n        {\n            uint qx = (uint)(((x % period) + period) % period), qy = (uint)(((y % period) + period) % period);\n            uint h = (qx * 1597334673u) ^ (qy * 3812015801u);\n            h = (h ^ (h >> 16)) * 2246822519u;\n            h ^= h >> 13;\n            return h / 4294967295f;\n        }\n\n        private static float Noise(float x, float y, int period)\n        {\n            int ix = (int)MathF.Floor(x), iy = (int)MathF.Floor(y);\n            float fx = x - ix, fy = y - iy;\n            fx = fx * fx * (3f - 2f * fx);\n            fy = fy * fy * (3f - 2f * fy);\n            float a = float.Lerp(Hash(ix, iy, period), Hash(ix + 1, iy, period), fx);\n            float b = float.Lerp(Hash(ix, iy + 1, period), Hash(ix + 1, iy + 1, period), fx);\n            return float.Lerp(a, b, fy);\n        }\n\n        // Three layers of noise, each finer, repeating every `period` units of the first.\n        private static float Layered(float x, float y, int period) =>\n            Noise(x, y, period) * 0.55f + Noise(x * 2f, y * 2f, period * 2) * 0.3f + Noise(x * 4f, y * 4f, period * 4) * 0.15f;\n    }\n}\n","NeonCity/Builder/CityBuilder.Streets.cs":"using System.Numerics;\n\nusing Vertex;\nusing Vertex.Physics;\nusing Vertex.Rendering;\n\nnamespace NeonCity.Builder\n{\n    // The streets, the buildings along them and the city beyond, the signs, lamps and stalls, and the walker.\n    //\n    // The main street runs along Z, the road from x = -5 to 5 with pavements out to 9 either side. A cross street runs\n    // along X at z = -36 to -28, and an alley goes off west at z = 18 to 26. The night market is on the east side,\n    // between z = 4 and 30 (see CityBuilder.Market.cs).\n    internal static partial class CityBuilder\n    {\n        private static Transform _bounds = null!;\n\n        private static void Streets()\n        {\n            Transform streets = Group(\"Streets\").Transform;\n            _bounds = Group(\"Bounds\").Transform;\n\n            var road = new MeshBuilder { TexturesPerUnit = 0.125f };\n            road.Span(new Vector3(-5f, -0.3f, -160f), new Vector3(5f, 0f, 66f));\n            road.Span(new Vector3(-70f, -0.3f, -36f), new Vector3(-5f, 0f, -28f));\n            road.Span(new Vector3(5f, -0.3f, -36f), new Vector3(70f, 0f, -28f));\n            road.Span(new Vector3(-30f, -0.3f, 18f), new Vector3(-9f, 0f, 26f));\n            Add(\"Road\", road, _road, streets, solid: true, shadows: false);\n\n            // Pavements, a step up from the road, with a kerb along the edge.\n            var pavements = new MeshBuilder { TexturesPerUnit = 0.5f };\n            var kerbs = new MeshBuilder();\n            void Pavement(float minX, float maxX, float minZ, float maxZ)\n            {\n                pavements.Span(new Vector3(minX, -0.3f, minZ), new Vector3(maxX, 0.15f, maxZ));\n                float kerbX = minX < 0f ? maxX : minX;\n                kerbs.Span(new Vector3(kerbX - 0.12f, -0.1f, minZ), new Vector3(kerbX + 0.12f, 0.16f, maxZ));\n            }\n\n            Pavement(-9f, -5f, 26f, 66f);\n            Pavement(-9f, -5f, -28f, 18f);\n            Pavement(-9f, -5f, -160f, -36f);\n            Pavement(5f, 9f, -28f, 66f);\n            Pavement(5f, 9f, -160f, -36f);\n            pavements.Span(new Vector3(-9f, -0.3f, 18f), new Vector3(-5f, 0.15f, 26f));\n            Add(\"Pavements\", pavements, _sidewalk, streets, solid: true, shadows: false);\n            Add(\"Kerbs\", kerbs, _wallMaterial, streets, solid: true, shadows: false);\n\n            // Dashes down the middle, lines along the edges, and crossings either side of the cross street.\n            var marks = new MeshBuilder();\n            for (float z = -158f; z < 64f; z += 6f)\n            {\n                if (z > -40f && z < -24f) continue;\n                marks.Span(new Vector3(-0.08f, 0f, z), new Vector3(0.08f, 0.012f, z + 3f));\n            }\n\n            foreach (float x in (ReadOnlySpan<float>)[-4.6f, 4.6f])\n            {\n                marks.Span(new Vector3(x - 0.06f, 0f, -24f), new Vector3(x + 0.06f, 0.012f, 64f));\n                marks.Span(new Vector3(x - 0.06f, 0f, -158f), new Vector3(x + 0.06f, 0.012f, -40f));\n            }\n\n            for (float x = -4.3f; x < 4.4f; x += 1f)\n            {\n                marks.Span(new Vector3(x, 0f, -40.5f), new Vector3(x + 0.5f, 0.012f, -37.2f));\n                marks.Span(new Vector3(x, 0f, -26.8f), new Vector3(x + 0.5f, 0.012f, -23.5f));\n            }\n\n            Add(\"Road Markings\", marks, _marking, streets, shadows: false);\n\n            // Puddles, still and black, catching the lights.\n            var puddles = new MeshBuilder();\n            for (int i = 0; i < 18; i++)\n            {\n                bool onPavement = i % 3 == 0;\n                float x = onPavement ? (i % 2 == 0 ? Range(-8.5f, -5.6f) : Range(5.6f, 8.5f)) : Range(-4.4f, 4.4f);\n                float z = Range(-120f, 62f);\n                float y = onPavement ? 0.152f : 0.004f;\n                var size = new Vector2(Range(0.7f, onPavement ? 2f : 3.2f), Range(1f, 4.5f));\n                puddles.Span(new Vector3(x - size.X * 0.5f, y - 0.004f, z - size.Y * 0.5f), new Vector3(x + size.X * 0.5f, y + 0.008f, z + size.Y * 0.5f));\n            }\n\n            Add(\"Puddles\", puddles, _puddle, streets, shadows: false);\n\n            // The ground beyond, under the city round about.\n            var ground = new MeshBuilder { TexturesPerUnit = 0.05f };\n            ground.Span(new Vector3(-400f, -0.6f, -500f), new Vector3(400f, -0.05f, 260f));\n            Add(\"Ground\", ground, _ground, streets, shadows: false);\n\n            // Where the walkable streets end.\n            Wall(new Vector3(-9f, -1f, -96f), new Vector3(9f, 20f, -94f), _bounds);\n            Wall(new Vector3(-64f, -1f, -36f), new Vector3(-62f, 20f, -28f), _bounds);\n            Wall(new Vector3(62f, -1f, -36f), new Vector3(64f, 20f, -28f), _bounds);\n            Wall(new Vector3(28f, -1f, 30f), new Vector3(29f, 20f, 32f), _bounds);\n            Wall(new Vector3(12f, -1f, 0f), new Vector3(13f, 20f, 4f), _bounds);\n        }\n\n        // ---------------------------------------------------------------- Buildings\n\n        private static void Buildings()\n        {\n            Transform group = Group(\"Buildings\").Transform;\n\n            Building(group, \"Ramen House\", -26f, -9f, 26f, 62f, 34f);\n            Building(group, \"Arcade Tower\", -28f, -9f, -28f, 18f, 52f);\n            Building(group, \"West Tower\", -30f, -9f, -94f, -36f, 78f);\n            Building(group, \"Alley End\", -52f, -30f, 12f, 32f, 40f);\n            Building(group, \"Sushi Tower\", 9f, 28f, 32f, 62f, 46f);\n            Building(group, \"Billboard Tower\", 9f, 30f, -28f, 0f, 62f);\n            Building(group, \"East Tower\", 9f, 32f, -94f, -36f, 70f);\n            Building(group, \"North Block\", -26f, 28f, 66f, 92f, 30f);\n            Building(group, \"South West Tower\", -30f, -9f, -160f, -96f, 96f);\n            Building(group, \"South East Tower\", 9f, 32f, -160f, -96f, 112f);\n            Building(group, \"Cross Street North West\", -62f, -30f, -28f, -4f, 38f);\n            Building(group, \"Cross Street North East\", 32f, 64f, -28f, -4f, 48f);\n            Building(group, \"Cross Street South West\", -64f, -32f, -70f, -36f, 56f);\n            Building(group, \"Cross Street South East\", 34f, 66f, -70f, -36f, 40f);\n\n            Signs(Group(\"Signs\").Transform);\n        }\n\n        /// <summary>\n        /// A building filling a block, its street side set back at the bottom for shopfronts under a canopy, tall ones\n        /// narrowing near the top. Windows on every side but the back, some lit.\n        /// </summary>\n        private static void Building(Transform parent, string name, float minX, float maxX, float minZ, float maxZ, float height)\n        {\n            Transform building = Group(name, parent).Transform;\n            var shell = new MeshBuilder();\n            var windows = new MeshBuilder();\n            var trim = new MeshBuilder();\n            var shops = new MeshBuilder();\n            var glass = new MeshBuilder();\n\n            // Which side faces the street, and which is the back.\n            Vector3 street = minX >= 8f ? -Vector3.UnitX : maxX <= -8f ? Vector3.UnitX : -Vector3.UnitZ;\n            const float shopHeight = 4.4f;\n            const float setBack = 0.8f;\n\n            // The ground floor, set back on the street side; everything above it.\n            Vector3 min = new(minX, 0f, minZ), max = new(maxX, height, maxZ);\n            Vector3 groundMin = min - Vector3.Min(street, Vector3.Zero) * setBack, groundMax = new Vector3(maxX, shopHeight, maxZ) - Vector3.Max(street, Vector3.Zero) * setBack;\n            shell.Span(groundMin, groundMax);\n\n            float split = height > 40f ? MathF.Round(height * Range(0.55f, 0.75f) / 3.6f) * 3.6f + shopHeight : height;\n            shell.Span(new Vector3(minX, shopHeight, minZ), new Vector3(maxX, split, maxZ));\n            const float inset = 2f;\n            if (split < height) shell.Span(new Vector3(minX + inset, split, minZ + inset), new Vector3(maxX - inset, height, maxZ - inset));\n\n            float lit = Range(0.3f, 0.55f);\n            FacadeWindows(windows, minX, maxX, minZ, maxZ, shopHeight + 1f, split, street, lit);\n            if (split < height) FacadeWindows(windows, minX + inset, maxX - inset, minZ + inset, maxZ - inset, split + 1f, height, street, lit);\n\n            // Ledges every few floors on the street side, and a parapet round the roof.\n            (Vector3 faceAt, Vector3 along, float faceWidth) = Face(minX, maxX, minZ, maxZ, street);\n            for (float y = shopHeight + 3.6f * 4f; y < split - 2f; y += 3.6f * 4f)\n            {\n                trim.Box(faceAt + along * (faceWidth * 0.5f) + new Vector3(0f, y, 0f) + street * 0.12f, Size(along, faceWidth, 0.25f, 0.3f, street));\n            }\n\n            float roof = height;\n            float rMinX = split < height ? minX + inset : minX, rMaxX = split < height ? maxX - inset : maxX;\n            float rMinZ = split < height ? minZ + inset : minZ, rMaxZ = split < height ? maxZ - inset : maxZ;\n            trim.Span(new Vector3(rMinX, roof, rMinZ), new Vector3(rMaxX, roof + 0.9f, rMinZ + 0.3f));\n            trim.Span(new Vector3(rMinX, roof, rMaxZ - 0.3f), new Vector3(rMaxX, roof + 0.9f, rMaxZ));\n            trim.Span(new Vector3(rMinX, roof, rMinZ), new Vector3(rMinX + 0.3f, roof + 0.9f, rMaxZ));\n            trim.Span(new Vector3(rMaxX - 0.3f, roof, rMinZ), new Vector3(rMaxX, roof + 0.9f, rMaxZ));\n\n            // Machinery on the roof, and on tall ones a mast with a warning light.\n            for (int i = 0; i < 3; i++)\n            {\n                var at = new Vector3(Range(rMinX + 2f, rMaxX - 2f), roof, Range(rMinZ + 2f, rMaxZ - 2f));\n                var size = new Vector3(Range(1.5f, 4f), Range(1f, 3f), Range(1.5f, 4f));\n                shell.Box(at + new Vector3(0f, size.Y * 0.5f, 0f), size);\n            }\n\n            if (height > 45f)\n            {\n                var mast = new Vector3((rMinX + rMaxX) * 0.5f, roof, (rMinZ + rMaxZ) * 0.5f);\n                float tall = Range(6f, 14f);\n                trim.Beam(mast, mast + new Vector3(0f, tall, 0f), 0.25f);\n                var beacon = new MeshBuilder();\n                beacon.Box(Vector3.Zero, new Vector3(0.5f));\n                AddAt(\"Warning Light\", mast + new Vector3(0f, tall + 0.3f, 0f), beacon, Glow(new Color(1f, 0.08f, 0.05f), 12f), building, shadows: false)\n                    .AddComponent<Flicker>(f => { f.Style = FlickerStyle.Blink; f.Seconds = Range(1.6f, 2.4f); f.Low = 0f; });\n            }\n\n            // Shopfronts: lit shops and dark glass between steel posts, under a canopy with a strip of light beneath its edge.\n            Vector3 shopFace = faceAt + street * (-setBack + 0.02f);\n            for (float a = 0.5f; a + 3.5f <= faceWidth; a += 4f)\n            {\n                Vector3 centre = shopFace + along * (a + 1.75f) + new Vector3(0f, 2.1f, 0f);\n                (Vector2 shopMin, Vector2 shopMax) = WindowPicture(_random.Next(_litColors));\n                if (_random.NextSingle() < 0.55f) shops.Panel(centre, street, Vector3.UnitY, 3.5f, 3.4f, shopMin, shopMax);\n                else glass.Panel(centre, street, Vector3.UnitY, 3.5f, 3.4f);\n                trim.Box(shopFace + along * a + new Vector3(0f, shopHeight * 0.5f, 0f), Size(along, 0.18f, shopHeight, 0.18f, street));\n            }\n\n            Vector3 canopyMiddle = faceAt + along * (faceWidth * 0.5f) + street * 0.6f + new Vector3(0f, shopHeight - 0.15f, 0f);\n            trim.Box(canopyMiddle, Size(along, faceWidth, 0.3f, 1.2f + setBack, street));\n            var strip = new MeshBuilder();\n            strip.Box(canopyMiddle + street * 0.95f - new Vector3(0f, 0.17f, 0f), Size(along, faceWidth - 0.4f, 0.05f, 0.08f, street));\n\n            Add(\"Walls\", shell, _wallMaterial, building, solid: true);\n            Add(\"Windows\", windows, _windows, building, shadows: false);\n            Add(\"Trim\", trim, _darkMetal, building);\n            Add(\"Shops\", shops, _windows, building, shadows: false);\n            Add(\"Shop Glass\", glass, _glass, building, shadows: false);\n            Add(\"Canopy Light\", strip, Glow(Pick(new[] { new Color(1f, 0.75f, 0.45f), new Color(0.6f, 0.85f, 1f), new Color(1f, 0.4f, 0.7f) }), 3f), building, shadows: false);\n        }\n\n        /// <summary>A box's size given along the street face, up, and out from it.</summary>\n        private static Vector3 Size(Vector3 along, float alongSize, float up, float out_, Vector3 street) =>\n            MathF.Abs(along.X) > 0.5f ? new Vector3(alongSize, up, out_) : new Vector3(out_, up, alongSize);\n\n        /// <summary>The street side of a block: its corner at ground level, the way along it, and how wide it is.</summary>\n        private static (Vector3 Corner, Vector3 Along, float Width) Face(float minX, float maxX, float minZ, float maxZ, Vector3 street)\n        {\n            if (street.X < -0.5f) return (new Vector3(minX, 0f, minZ), Vector3.UnitZ, maxZ - minZ);\n            if (street.X > 0.5f) return (new Vector3(maxX, 0f, minZ), Vector3.UnitZ, maxZ - minZ);\n            return (new Vector3(minX, 0f, minZ), Vector3.UnitX, maxX - minX);\n        }\n\n        /// <summary>Rows of windows, a floor apart, on every side of a block but the one facing away from the street.</summary>\n        private static void FacadeWindows(MeshBuilder windows, float minX, float maxX, float minZ, float maxZ, float fromY, float toY, Vector3 street, float lit)\n        {\n            (Vector3 Corner, Vector3 Along, Vector3 Normal, float Width)[] faces =\n            [\n                (new Vector3(minX, 0f, minZ), Vector3.UnitZ, -Vector3.UnitX, maxZ - minZ),\n                (new Vector3(maxX, 0f, minZ), Vector3.UnitZ, Vector3.UnitX, maxZ - minZ),\n                (new Vector3(minX, 0f, minZ), Vector3.UnitX, -Vector3.UnitZ, maxX - minX),\n                (new Vector3(minX, 0f, maxZ), Vector3.UnitX, Vector3.UnitZ, maxX - minX)\n            ];\n\n            foreach ((Vector3 corner, Vector3 along, Vector3 normal, float width) in faces)\n            {\n                if (Vector3.Dot(normal, street) < -0.5f) continue;\n\n                for (float y = fromY; y + 2.4f < toY; y += 3.6f)\n                {\n                    bool darkFloor = _random.NextSingle() < 0.12f;\n                    int floorColor = _random.Next(_litColors);\n                    for (float a = 1.6f; a + 1.2f <= width; a += 2.7f)\n                    {\n                        // Lit windows on a floor are mostly the same colour, as one office or flat is.\n                        bool on = !darkFloor && _random.NextSingle() < lit;\n                        int color = on ? (_random.NextSingle() < 0.7f ? floorColor : _random.Next(_litColors)) : _litColors + _random.Next(_windowColors.Length - _litColors);\n                        Vector3 centre = corner + along * a + new Vector3(0f, y + 1.1f, 0f) + normal * 0.04f;\n                        (Vector2 pictureMin, Vector2 pictureMax) = WindowPicture(color);\n                        windows.Panel(centre, normal, Vector3.UnitY, 1.7f, 2.1f, pictureMin, pictureMax);\n                    }\n                }\n            }\n        }\n\n        // ---------------------------------------------------------------- Signs\n\n        private static readonly Color _pink = new(1f, 0.18f, 0.6f), _cyan = new(0.2f, 0.85f, 1f), _orange = new(1f, 0.5f, 0.12f),\n            _purple = new(0.65f, 0.3f, 1f), _green = new(0.3f, 1f, 0.45f), _gold = new(1f, 0.75f, 0.2f), _blue = new(0.25f, 0.45f, 1f),\n            _red = new(1f, 0.12f, 0.1f);\n\n        private static void Signs(Transform group)\n        {\n            // Flat on the west side's walls they face +X, read with right along -Z; on the east side they face -X, right along +Z.\n            Vector3 westRight = -Vector3.UnitZ, eastRight = Vector3.UnitZ, up = Vector3.UnitY;\n\n            NeonSign(\"Ramen Sign\", \"RAMEN\", new Vector3(-8.75f, 5.4f, 46f), westRight, up, _pink, 0.9f, group);\n            NeonSign(\"Hotel Sign\", \"HOTEL\", new Vector3(-8.25f, 12f, 30.5f), Vector3.UnitX, up, _cyan, 1.2f, group, vertical: true, twoSided: true);\n            GlyphSign(\"Ramen House Sign\", 4, new Vector3(-8.1f, 10f, 57f), Vector3.UnitX, up, _orange, 1f, group, twoSided: true);\n\n            NeonSign(\"Arcade Sign\", \"ARCADE\", new Vector3(-8.75f, 5.4f, 2f), westRight, up, _purple, 1f, group);\n            NeonSign(\"Karaoke Sign\", \"KARAOKE\", new Vector3(-8.3f, 15f, -14f), Vector3.UnitX, up, _orange, 1.1f, group, vertical: true, twoSided: true);\n            GlyphSign(\"Arcade Tower Sign\", 5, new Vector3(-8.1f, 11f, 12f), Vector3.UnitX, up, _green, 1f, group, twoSided: true);\n            NeonSign(\"Open All Night Sign\", \"24H\", new Vector3(-8.1f, 3.1f, -9f), westRight, up, _green, 0.5f, group, light: 1.2f, flicker: FlickerStyle.Buzz);\n\n            NeonSign(\"Drink Sign\", \"DRINK\", new Vector3(-8.75f, 5.4f, -52f), westRight, up, _blue, 0.9f, group);\n            GlyphSign(\"West Tower Sign\", 6, new Vector3(-7.95f, 17f, -72f), Vector3.UnitX, up, _pink, 1.2f, group, twoSided: true);\n\n            NeonSign(\"Sushi Sign\", \"SUSHI\", new Vector3(8.3f, 12f, 52f), Vector3.UnitX, up, _orange, 1.1f, group, vertical: true, twoSided: true);\n            NeonSign(\"Open Sign\", \"OPEN\", new Vector3(8.1f, 3.1f, 40f), eastRight, up, _green, 0.5f, group, light: 1.2f, flicker: FlickerStyle.Buzz);\n            GlyphSign(\"Sushi Tower Sign\", 4, new Vector3(8.17f, 9f, 37f), Vector3.UnitX, up, _purple, 0.9f, group, twoSided: true);\n\n            NeonSign(\"Bar Sign\", \"BAR\", new Vector3(8.1f, 3.1f, -21f), eastRight, up, _blue, 0.6f, group, light: 1.5f, flicker: FlickerStyle.Buzz);\n            NeonSign(\"Pachinko Sign\", \"PACHINKO\", new Vector3(8.2f, 19f, -62f), Vector3.UnitX, up, _gold, 1.3f, group, vertical: true, twoSided: true);\n            GlyphSign(\"East Tower Sign\", 5, new Vector3(8.75f, 12f, -44f), eastRight, up, _cyan, 1.1f, group);\n\n            NeonSign(\"Vertex Sign\", \"VERTEX\", new Vector3(1f, 16f, 65.7f), -Vector3.UnitX, up, _cyan, 2.2f, group, light: 4f);\n            NeonSign(\"Exit Sign\", \"EXIT\", new Vector3(-29.75f, 3.2f, 22f), westRight, up, _red, 0.45f, group, light: 1.2f, flicker: FlickerStyle.Buzz);\n\n            // The big screen on the billboard tower: one picture, its colour (and the light it throws on the street) changing.\n            var screen = new MeshBuilder();\n            screen.Panel(new Vector3(2.35f, 0f, 0f), -Vector3.UnitX, up, 9f, 18f);\n            GameObject advert = AddAt(\"Big Screen\", new Vector3(6.5f, 19f, -14f), screen, Picture(_advert, Color.White), group, shadows: false);\n            advert.AddComponent<Light>(light =>\n            {\n                light.Type = LightType.Point;\n                light.Intensity = 3f;\n                light.Range = 24f;\n                light.FogStrength = 1.3f;\n                light.CastShadows = false;\n            });\n            advert.AddComponent<ColorCycle>(cycle => cycle.TintColor = true);\n\n            var frame = new MeshBuilder();\n            Vector3[] corners = [new(8.8f, 9.8f, -18.6f), new(8.8f, 9.8f, -9.4f), new(8.8f, 28.2f, -9.4f), new(8.8f, 28.2f, -18.6f)];\n            for (int i = 0; i < 4; i++) frame.Beam(corners[i], corners[(i + 1) % 4], 0.12f, -Vector3.UnitX);\n            Add(\"Big Screen Frame\", frame, Glow(_cyan, 4f), group, shadows: false);\n        }\n    }\n}\n","NeonCity/Builder/MeshBuilder.cs":"using System.Numerics;\n\nusing Vertex.Rendering;\n\nnamespace NeonCity.Builder\n{\n    /// <summary>\n    /// Gathers boxes and flat pieces into one mesh, so a whole building's walls, or every letter of a sign, is one draw.\n    /// Texture coordinates are in world units times <see cref=\"TexturesPerUnit\"/>, so a texture tiles evenly however big\n    /// each piece is.\n    /// </summary>\n    internal sealed class MeshBuilder\n    {\n        private readonly List<MeshVertex> _vertices = new();\n        private readonly List<uint> _indices = new();\n\n        /// <summary>How many times a texture repeats per unit.</summary>\n        public float TexturesPerUnit { get; set; } = 0.25f;\n\n        public bool IsEmpty => _indices.Count == 0;\n\n        /// <summary>\n        /// A flat four-cornered piece facing <paramref name=\"normal\"/>: corners counter-clockwise seen from in front, with\n        /// the texture's corners at <paramref name=\"uvMin\"/> and <paramref name=\"uvMax\"/>.\n        /// </summary>\n        public void Quad(Vector3 a, Vector3 b, Vector3 c, Vector3 d, Vector3 normal, Vector2 uvMin, Vector2 uvMax)\n        {\n            uint first = (uint)_vertices.Count;\n            _vertices.Add(new MeshVertex(a, normal, new Vector2(uvMin.X, uvMax.Y)));\n            _vertices.Add(new MeshVertex(b, normal, new Vector2(uvMax.X, uvMax.Y)));\n            _vertices.Add(new MeshVertex(c, normal, new Vector2(uvMax.X, uvMin.Y)));\n            _vertices.Add(new MeshVertex(d, normal, new Vector2(uvMin.X, uvMin.Y)));\n            _indices.AddRange([first, first + 1, first + 2, first, first + 2, first + 3]);\n        }\n\n        /// <summary>A flat rectangle centred on <paramref name=\"centre\"/>, facing <paramref name=\"normal\"/>, with <paramref name=\"up\"/> along its height.</summary>\n        public void Panel(Vector3 centre, Vector3 normal, Vector3 up, float width, float height, Vector2? uvMin = null, Vector2? uvMax = null)\n        {\n            Vector3 right = Vector3.Normalize(Vector3.Cross(up, normal)) * (width * 0.5f);\n            Vector3 top = Vector3.Normalize(up) * (height * 0.5f);\n            Quad(centre - right - top, centre + right - top, centre + right + top, centre - right + top, Vector3.Normalize(normal),\n                uvMin ?? Vector2.Zero, uvMax ?? Vector2.One);\n        }\n\n        /// <summary>A box lined up with the world's axes.</summary>\n        public void Box(Vector3 centre, Vector3 size) => Box(centre, Vector3.UnitX, Vector3.UnitY, Vector3.UnitZ, size);\n\n        /// <summary>A box from <paramref name=\"min\"/> to <paramref name=\"max\"/>.</summary>\n        public void Span(Vector3 min, Vector3 max) => Box((min + max) * 0.5f, max - min);\n\n        /// <summary>A box turned <paramref name=\"yaw\"/> degrees about the vertical.</summary>\n        public void Box(Vector3 centre, Vector3 size, float yaw)\n        {\n            Quaternion turn = Quaternion.CreateFromAxisAngle(Vector3.UnitY, yaw * MathF.PI / 180f);\n            Box(centre, Vector3.Transform(Vector3.UnitX, turn), Vector3.UnitY, Vector3.Transform(Vector3.UnitZ, turn), size);\n        }\n\n        /// <summary>A box whose sides run along <paramref name=\"x\"/>, <paramref name=\"y\"/> and <paramref name=\"z\"/> (at right angles), <paramref name=\"size\"/> along each.</summary>\n        public void Box(Vector3 centre, Vector3 x, Vector3 y, Vector3 z, Vector3 size)\n        {\n            Vector3 hx = x * (size.X * 0.5f), hy = y * (size.Y * 0.5f), hz = z * (size.Z * 0.5f);\n\n            // Each side: its outward direction, and two along it whose cross product is that direction, so the corners\n            // go round counter-clockwise seen from outside.\n            Face(centre + hx, x, -z, y, size.Z, size.Y);\n            Face(centre - hx, -x, z, y, size.Z, size.Y);\n            Face(centre + hz, z, x, y, size.X, size.Y);\n            Face(centre - hz, -z, -x, y, size.X, size.Y);\n            Face(centre + hy, y, x, -z, size.X, size.Z);\n            Face(centre - hy, -y, x, z, size.X, size.Z);\n        }\n\n        /// <summary>A long box from <paramref name=\"from\"/> to <paramref name=\"to\"/>, <paramref name=\"thickness\"/> across: a pipe, a cable, a neon tube.</summary>\n        public void Beam(Vector3 from, Vector3 to, float thickness, Vector3? side = null)\n        {\n            Vector3 along = to - from;\n            float length = along.Length();\n            if (length < 1e-4f) return;\n\n            along /= length;\n            Vector3 across = side ?? (MathF.Abs(along.Y) < 0.95f ? Vector3.UnitY : Vector3.UnitX);\n            Vector3 z = Vector3.Normalize(Vector3.Cross(along, across));\n            Vector3 y = Vector3.Cross(z, along);\n\n            // A little longer than the gap, so joined tubes meet without a notch at the corner.\n            Box((from + to) * 0.5f, along, y, z, new Vector3(length + thickness, thickness, thickness));\n        }\n\n        private void Face(Vector3 centre, Vector3 normal, Vector3 u, Vector3 v, float width, float height)\n        {\n            Vector3 hu = u * (width * 0.5f), hv = v * (height * 0.5f);\n            float scale = TexturesPerUnit;\n\n            // Textures keep their place on the wall, so neighbouring boxes line up.\n            Vector2 offset = new(Vector3.Dot(centre, u), -Vector3.Dot(centre, v));\n            Vector2 half = new(width * 0.5f, height * 0.5f);\n            Quad(centre - hu - hv, centre + hu - hv, centre + hu + hv, centre - hu + hv, normal, (offset - half) * scale, (offset + half) * scale);\n        }\n\n        public Mesh Build() => new(_vertices.ToArray(), _indices.ToArray());\n    }\n}\n","NeonCity/Builder/NeonFont.cs":"using System.Numerics;\n\nnamespace NeonCity.Builder\n{\n    /// <summary>\n    /// Letters drawn as bent neon tubes: each is a few lines on a grid 4 wide and 6 high, which the builder turns into\n    /// glowing tubes. Capitals, numbers and a few marks.\n    /// </summary>\n    internal static class NeonFont\n    {\n        public const float Width = 4f;\n        public const float Height = 6f;\n\n        /// <summary>How far along each letter starts from the last, in grid units.</summary>\n        public const float Advance = 5.6f;\n\n        private static readonly Vector2[] _o = P(1, 0, 0, 1, 0, 5, 1, 6, 3, 6, 4, 5, 4, 1, 3, 0, 1, 0);\n        private static readonly Vector2[] _p = P(0, 0, 0, 6, 3, 6, 4, 5, 4, 4, 3, 3, 0, 3);\n\n        private static readonly Dictionary<char, Vector2[][]> _strokes = new()\n        {\n            ['A'] = [P(0, 0, 0, 4, 2, 6, 4, 4, 4, 0), P(0, 3, 4, 3)],\n            ['B'] = [P(0, 0, 0, 6, 3, 6, 4, 5, 4, 4, 3, 3, 0, 3), P(3, 3, 4, 2, 4, 1, 3, 0, 0, 0)],\n            ['C'] = [P(4, 6, 1, 6, 0, 5, 0, 1, 1, 0, 4, 0)],\n            ['D'] = [P(0, 0, 0, 6, 3, 6, 4, 5, 4, 1, 3, 0, 0, 0)],\n            ['E'] = [P(4, 6, 0, 6, 0, 0, 4, 0), P(0, 3, 3, 3)],\n            ['F'] = [P(4, 6, 0, 6, 0, 0), P(0, 3, 3, 3)],\n            ['G'] = [P(4, 5, 3, 6, 1, 6, 0, 5, 0, 1, 1, 0, 3, 0, 4, 1, 4, 3, 2, 3)],\n            ['H'] = [P(0, 0, 0, 6), P(4, 0, 4, 6), P(0, 3, 4, 3)],\n            ['I'] = [P(1, 6, 3, 6), P(2, 6, 2, 0), P(1, 0, 3, 0)],\n            ['J'] = [P(4, 6, 4, 1, 3, 0, 1, 0, 0, 1)],\n            ['K'] = [P(0, 0, 0, 6), P(4, 6, 0, 2), P(1, 3, 4, 0)],\n            ['L'] = [P(0, 6, 0, 0, 4, 0)],\n            ['M'] = [P(0, 0, 0, 6, 2, 3, 4, 6, 4, 0)],\n            ['N'] = [P(0, 0, 0, 6, 4, 0, 4, 6)],\n            ['O'] = [_o],\n            ['P'] = [_p],\n            ['Q'] = [_o, P(2, 2, 4, 0)],\n            ['R'] = [_p, P(2, 3, 4, 0)],\n            ['S'] = [P(4, 5, 3, 6, 1, 6, 0, 5, 0, 4, 1, 3, 3, 3, 4, 2, 4, 1, 3, 0, 1, 0, 0, 1)],\n            ['T'] = [P(0, 6, 4, 6), P(2, 6, 2, 0)],\n            ['U'] = [P(0, 6, 0, 1, 1, 0, 3, 0, 4, 1, 4, 6)],\n            ['V'] = [P(0, 6, 2, 0, 4, 6)],\n            ['W'] = [P(0, 6, 1, 0, 2, 3, 3, 0, 4, 6)],\n            ['X'] = [P(0, 6, 4, 0), P(4, 6, 0, 0)],\n            ['Y'] = [P(0, 6, 2, 3, 4, 6), P(2, 3, 2, 0)],\n            ['Z'] = [P(0, 6, 4, 6, 0, 0, 4, 0)],\n            ['0'] = [_o, P(1, 1, 3, 5)],\n            ['1'] = [P(1, 5, 2, 6, 2, 0), P(1, 0, 3, 0)],\n            ['2'] = [P(0, 5, 1, 6, 3, 6, 4, 5, 4, 4, 0, 0, 4, 0)],\n            ['3'] = [P(0, 5, 1, 6, 3, 6, 4, 5, 4, 4, 3, 3, 4, 2, 4, 1, 3, 0, 1, 0, 0, 1), P(1, 3, 3, 3)],\n            ['4'] = [P(3, 0, 3, 6, 0, 2, 4, 2)],\n            ['5'] = [P(4, 6, 0, 6, 0, 3, 3, 3, 4, 2, 4, 1, 3, 0, 0, 0)],\n            ['6'] = [P(4, 6, 1, 6, 0, 5, 0, 1, 1, 0, 3, 0, 4, 1, 4, 2, 3, 3, 0, 3)],\n            ['7'] = [P(0, 6, 4, 6, 1, 0)],\n            ['8'] = [P(1, 3, 0, 4, 0, 5, 1, 6, 3, 6, 4, 5, 4, 4, 3, 3, 1, 3, 0, 2, 0, 1, 1, 0, 3, 0, 4, 1, 4, 2, 3, 3)],\n            ['9'] = [P(4, 3, 1, 3, 0, 4, 0, 5, 1, 6, 3, 6, 4, 5, 4, 1, 3, 0, 0, 0)],\n            ['-'] = [P(1, 3, 3, 3)],\n            ['+'] = [P(0, 3, 4, 3), P(2, 1, 2, 5)],\n            ['*'] = [P(2, 1, 2, 5), P(0, 2, 4, 4), P(0, 4, 4, 2)],\n            ['!'] = [P(2, 6, 2, 2), P(2, 0.6f, 2, 0)],\n            ['.'] = [P(2, 0.6f, 2, 0)]\n        };\n\n        /// <summary>The lines of a letter (each a run of points joined in order), or none for a space or one it doesn't have.</summary>\n        public static IReadOnlyList<Vector2[]> Strokes(char letter) => _strokes.TryGetValue(char.ToUpperInvariant(letter), out Vector2[][]? strokes) ? strokes : [];\n\n        /// <summary>How wide <paramref name=\"text\"/> is in grid units, written in a line.</summary>\n        public static float LineWidth(string text) => text.Length == 0 ? 0f : (text.Length - 1) * Advance + Width;\n\n        private static Vector2[] P(params float[] xy)\n        {\n            var points = new Vector2[xy.Length / 2];\n            for (int i = 0; i < points.Length; i++) points[i] = new Vector2(xy[i * 2], xy[i * 2 + 1]);\n            return points;\n        }\n    }\n}\n","NeonCity/Builder/Png.cs":"using System.IO.Compression;\nusing System.Text;\n\nnamespace NeonCity.Builder\n{\n    /// <summary>Writes RGBA pixels as a PNG file, so the builder's textures are ordinary image files the editor can show.</summary>\n    internal static class Png\n    {\n        public static void Save(string path, int width, int height, byte[] rgba)\n        {\n            // Each row starts with a byte saying how it's filtered: 0, not at all.\n            var raw = new byte[height * (width * 4 + 1)];\n            for (int y = 0; y < height; y++) Array.Copy(rgba, y * width * 4, raw, y * (width * 4 + 1) + 1, width * 4);\n\n            using var compressed = new MemoryStream();\n            using (var zlib = new ZLibStream(compressed, CompressionLevel.Optimal, leaveOpen: true)) zlib.Write(raw);\n\n            using var file = File.Create(path);\n            file.Write([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]);\n\n            var header = new byte[13];\n            WriteBigEndian(header, 0, (uint)width);\n            WriteBigEndian(header, 4, (uint)height);\n            header[8] = 8;   // bits per channel\n            header[9] = 6;   // red, green, blue and alpha\n            Chunk(file, \"IHDR\", header);\n            Chunk(file, \"IDAT\", compressed.ToArray());\n            Chunk(file, \"IEND\", []);\n        }\n\n        private static void Chunk(Stream file, string type, byte[] data)\n        {\n            var length = new byte[4];\n            WriteBigEndian(length, 0, (uint)data.Length);\n            file.Write(length);\n\n            byte[] typed = [.. Encoding.ASCII.GetBytes(type), .. data];\n            file.Write(typed);\n\n            var crc = new byte[4];\n            WriteBigEndian(crc, 0, Crc(typed));\n            file.Write(crc);\n        }\n\n        private static void WriteBigEndian(byte[] into, int at, uint value)\n        {\n            into[at] = (byte)(value >> 24);\n            into[at + 1] = (byte)(value >> 16);\n            into[at + 2] = (byte)(value >> 8);\n            into[at + 3] = (byte)value;\n        }\n\n        private static uint Crc(byte[] data)\n        {\n            uint crc = 0xFFFFFFFF;\n            foreach (byte b in data)\n            {\n                crc ^= b;\n                for (int i = 0; i < 8; i++) crc = (crc & 1) != 0 ? 0xEDB88320 ^ (crc >> 1) : crc >> 1;\n            }\n\n            return crc ^ 0xFFFFFFFF;\n        }\n    }\n}\n","NeonCity/Program.cs":"using Vertex;\n\n// Walks round the city. \"--build\" makes its scene and textures again from the code in Builder, over what's in Assets:\n// run it after changing the builder, but not after changing the scene in the editor, or those changes are lost.\nif (args.Contains(\"--build\"))\n{\n    string assets = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory, \"..\", \"..\", \"..\", \"Assets\"));\n    NeonCity.Builder.CityBuilder.Build(assets);\n    return;\n}\n\nnew Game { StartScene = \"Scenes/Neon City.scene\" }.Run(\"Neon City\");\n"};
